window.getMeowlimeGrowthState = function() {
    if (!window.__meowlimeGrowthState) {
        window.__meowlimeGrowthState = {
            running: false,
            rafId: null,
            lastTs: 0,
            x: 0,
            y: 0,
            targetX: 0,
            targetY: 0,
            nextTargetAt: 0,
            floatSeed: Math.random() * 1000,
            expression: '^⦁⩊⦁^',
            jiggleUntil: 0,
            touchPulseUntil: 0,
            touchPulseStart: 0,
            touchHueShift: 0,
            stretchPower: 0,
            stretchAngle: 0,
            dragDX: 0,
            dragDY: 0,
            pointerId: null,
            pointerDownAt: 0,
            pointerStartX: 0,
            pointerStartY: 0,
            isPointerDown: false,
            isHolding: false,
            dragging: false,
            holdTimer: null,
            releaseBounceUntil: 0,
            boundCanvas: null,
            boundModal: null,
            pointerHandler: null,
            pointerMoveHandler: null,
            pointerUpHandler: null,
            pointerCancelHandler: null,
            pointerLeaveHandler: null,
            lostPointerCaptureHandler: null,
            mouseUpHandler: null,
            modalStopHandler: null,
            resizeHandler: null
        };
    }
    return window.__meowlimeGrowthState;
};

window.stopMeowlimeGrowthCanvas = function() {
    const state = window.getMeowlimeGrowthState ? window.getMeowlimeGrowthState() : null;
    if (!state) return;

    state.running = false;

    if (state.rafId) {
        cancelAnimationFrame(state.rafId);
        state.rafId = null;
    }

    if (state.holdTimer) {
        clearTimeout(state.holdTimer);
        state.holdTimer = null;
    }

    if (state.boundCanvas && state.pointerHandler) {
        state.boundCanvas.removeEventListener('pointerdown', state.pointerHandler);
    }

    if (state.pointerMoveHandler) {
        window.removeEventListener('pointermove', state.pointerMoveHandler);
    }

    if (state.pointerUpHandler) {
        window.removeEventListener('pointerup', state.pointerUpHandler);
    }

    if (state.pointerCancelHandler) {
        window.removeEventListener('pointercancel', state.pointerCancelHandler);
    }

    if (state.boundCanvas && state.pointerLeaveHandler) {
        state.boundCanvas.removeEventListener('pointerleave', state.pointerLeaveHandler);
    }

    if (state.boundCanvas && state.lostPointerCaptureHandler) {
        state.boundCanvas.removeEventListener('lostpointercapture', state.lostPointerCaptureHandler);
    }

    if (state.mouseUpHandler) {
        window.removeEventListener('mouseup', state.mouseUpHandler);
    }

    if (state.boundModal && state.modalStopHandler) {
        state.boundModal.removeEventListener('pointerdown', state.modalStopHandler);
        state.boundModal.removeEventListener('click', state.modalStopHandler);
    }

    if (state.resizeHandler) {
        window.removeEventListener('resize', state.resizeHandler);
    }

    state.boundCanvas = null;
    state.boundModal = null;
    state.pointerHandler = null;
    state.pointerMoveHandler = null;
    state.pointerUpHandler = null;
    state.pointerCancelHandler = null;
    state.pointerLeaveHandler = null;
    state.lostPointerCaptureHandler = null;
    state.mouseUpHandler = null;
    state.modalStopHandler = null;
    state.resizeHandler = null;
    state.lastTs = 0;
    state.pointerId = null;
    state.pointerDownAt = 0;
    state.pointerStartX = 0;
    state.pointerStartY = 0;
    state.isPointerDown = false;
    state.isHolding = false;
    state.dragging = false;
    state.dragDX = 0;
    state.dragDY = 0;
    state.stretchPower = 0;
    state.releaseBounceUntil = 0;
};

window.resizeMeowlimeGrowthCanvas = function(canvas) {
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
    const nextWidth = Math.max(1, Math.floor(rect.width * dpr));
    const nextHeight = Math.max(1, Math.floor(rect.height * dpr));

    if (canvas.width !== nextWidth || canvas.height !== nextHeight) {
        canvas.width = nextWidth;
        canvas.height = nextHeight;
    }
};

window.drawMeowlimeGrowthBackground = function(ctx, w, h, t) {
    const centerX = w / 2;
    const centerY = h * 0.52;

    ctx.fillStyle = '#02030a';
    ctx.fillRect(0, 0, w, h);

    const glow = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, Math.max(w, h) * 0.68);
    glow.addColorStop(0, `hsla(${(t * 34) % 360}, 100%, 58%, 0.16)`);
    glow.addColorStop(0.42, 'rgba(10, 18, 34, 0.86)');
    glow.addColorStop(1, 'rgba(0, 0, 0, 0.98)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, w, h);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.lineWidth = Math.max(1, w * 0.002);

    for (let i = 0; i < 22; i++) {
        const angle = (Math.PI * 2 * i / 22) + t * 0.14;
        const hue = (t * 45 + i * 37) % 360;
        const outerX = centerX + Math.cos(angle) * Math.max(w, h) * 0.72;
        const outerY = centerY + Math.sin(angle) * Math.max(w, h) * 0.72;
        ctx.strokeStyle = `hsla(${hue}, 100%, 64%, 0.34)`;
        ctx.beginPath();
        ctx.moveTo(outerX, outerY);
        ctx.lineTo(centerX, centerY);
        ctx.stroke();
    }

    for (let r = 0; r < 9; r++) {
        const pulse = ((t * 0.18 + r * 0.115) % 1);
        const scale = 0.08 + pulse * 1.05;
        const rw = w * scale;
        const rh = h * scale * 0.62;
        const hue = (t * 58 + r * 41) % 360;

        ctx.strokeStyle = `hsla(${hue}, 100%, 62%, ${0.42 - pulse * 0.24})`;
        ctx.lineWidth = Math.max(1, 2.2 - pulse);
        ctx.strokeRect(centerX - rw / 2, centerY - rh / 2, rw, rh);

        if (r % 2 === 0) {
            ctx.fillStyle = `hsla(${(hue + 80) % 360}, 100%, 60%, ${0.12 - pulse * 0.06})`;
            ctx.fillRect(centerX - rw / 2, centerY - rh / 2, Math.max(2, rw * 0.025), Math.max(2, rh * 0.12));
            ctx.fillRect(centerX + rw / 2 - Math.max(2, rw * 0.025), centerY + rh / 2 - Math.max(2, rh * 0.12), Math.max(2, rw * 0.025), Math.max(2, rh * 0.12));
        }
    }

    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.22;
    ctx.strokeStyle = '#8fffee';
    ctx.lineWidth = 1;
    const gap = Math.max(18, w / 24);
    const offset = (t * 18) % gap;
    for (let x = -gap; x < w + gap; x += gap) {
        ctx.beginPath();
        ctx.moveTo(x + offset, 0);
        ctx.lineTo(centerX + (x - centerX) * 0.18, centerY);
        ctx.stroke();
    }
    for (let y = -gap; y < h + gap; y += gap) {
        ctx.beginPath();
        ctx.moveTo(0, y + offset);
        ctx.lineTo(centerX, centerY + (y - centerY) * 0.18);
        ctx.stroke();
    }
    ctx.restore();
};

window.drawMeowlimeGrowthBlob = function(ctx, x, y, size, expression, t, jigglePower, options = {}) {
    const radius = size / 2;
    const touchGlow = Math.max(0, Math.min(1, Number(options.touchGlow || 0)));
    const stretchPower = Math.max(0, Math.min(0.72, Number(options.stretchPower || 0)));
    const stretchAngle = Number.isFinite(options.stretchAngle) ? options.stretchAngle : 0;

    const wobbleA = Math.sin(t * 3.4) * 0.05 + jigglePower * Math.sin(t * 38) * 0.12;
    const wobbleB = Math.cos(t * 2.7) * 0.045 + jigglePower * Math.cos(t * 31) * 0.1;
    const hueShift = Number(options.hueShift || 0);
    const baseHue = (t * 24 + hueShift + touchGlow * 75) % 360;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(stretchAngle);
    ctx.scale(
        1 + wobbleA + stretchPower * 0.88,
        Math.max(0.66, 1 + wobbleB - stretchPower * 0.24)
    );

    ctx.shadowColor = touchGlow > 0
        ? 'rgba(255, 245, 180, 0.92)'
        : 'rgba(160, 245, 255, 0.72)';
    ctx.shadowBlur = Math.max(8, radius * (0.28 + touchGlow * 0.38));

    const grad = ctx.createRadialGradient(-radius * 0.28, -radius * 0.35, radius * 0.1, 0, 0, radius * (1 + stretchPower * 0.22));
    grad.addColorStop(0, `rgba(255,255,255,${0.88 + touchGlow * 0.08})`);
    grad.addColorStop(0.24, `hsla(${baseHue}, 100%, ${88 - touchGlow * 8}%, ${0.94 + touchGlow * 0.04})`);
    grad.addColorStop(0.56, `hsla(${(baseHue + 92) % 360}, 100%, ${82 - touchGlow * 7}%, ${0.92 + touchGlow * 0.05})`);
    grad.addColorStop(1, `hsla(${(baseHue + 174) % 360}, ${94 + touchGlow * 6}%, ${74 - touchGlow * 5}%, ${0.92 + touchGlow * 0.05})`);

    ctx.beginPath();
    const steps = 52;
    for (let i = 0; i <= steps; i++) {
        const a = Math.PI * 2 * i / steps;
        const frontPull = Math.max(0, Math.cos(a)) * radius * stretchPower * 0.42;
        const sideSqueeze = 1 - stretchPower * 0.08 * Math.abs(Math.sin(a));
        const n = 1
            + Math.sin(a * 3 + t * 2.2) * 0.055
            + Math.cos(a * 5 - t * 1.8) * 0.04
            + jigglePower * Math.sin(a * 8 + t * 42) * 0.055;

        const px = Math.cos(a) * radius * n * sideSqueeze + frontPull;
        const py = Math.sin(a) * radius * (0.92 + Math.cos(a * 2 - t) * 0.035) * n * (1 - stretchPower * 0.1);

        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.globalAlpha = 0.72 + touchGlow * 0.22;
    ctx.strokeStyle = touchGlow > 0 ? 'rgba(255,255,210,0.92)' : 'rgba(255,255,255,0.72)';
    ctx.lineWidth = Math.max(1.2, radius * (0.045 + touchGlow * 0.018));
    ctx.stroke();

    ctx.globalAlpha = 1;
    ctx.rotate(-stretchAngle);
    ctx.fillStyle = touchGlow > 0 ? 'rgba(20, 58, 70, 0.96)' : 'rgba(38, 70, 78, 0.92)';
    ctx.font = `900 ${Math.max(8, size * 0.17)}px "Microsoft JhengHei", "PingFang TC", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = 'rgba(255,255,255,0.82)';
    ctx.shadowBlur = Math.max(2, size * (0.04 + touchGlow * 0.035));
    ctx.fillText(expression || '^⦁⩊⦁^', 0, size * 0.015);

    ctx.restore();
};


window.getMeowlimeGrowthPointerPoint = function(canvas, e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / Math.max(1, rect.width);
    const scaleY = canvas.height / Math.max(1, rect.height);

    return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY
    };
};

window.pickMeowlimeGrowthTarget = function(state, w, h, size, dpr) {
    const marginX = size / 2 + 18 * dpr;
    const marginY = size / 2 + 18 * dpr;
    const minX = Math.min(w / 2, marginX);
    const maxX = Math.max(minX, w - marginX);
    const minY = Math.min(h / 2, marginY);
    const maxY = Math.max(minY, h - marginY);

    state.targetX = minX + Math.random() * Math.max(1, maxX - minX);
    state.targetY = minY + Math.random() * Math.max(1, maxY - minY);
    state.nextTargetAt = ((window.performance && performance.now) ? performance.now() : Date.now()) + 1800 + Math.random() * 2600;
};

window.renderMeowlimeGrowthFrame = function(ts) {
    const state = window.getMeowlimeGrowthState();
    const canvas = document.getElementById('meowlime-growth-canvas');

    if (!state.running || !canvas) return;

    window.resizeMeowlimeGrowthCanvas(canvas);

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const w = canvas.width;
    const h = canvas.height;
    const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
    const dt = state.lastTs ? Math.min(0.05, (ts - state.lastTs) / 1000) : 0.016;
    state.lastTs = ts;

    const growthSize = window.getMeowlimeGrowthSize ? window.getMeowlimeGrowthSize() : 20;
    const maxDrawableSize = Math.max(12, Math.min(w, h) - 36 * dpr);
    const edgeSafeSize = Math.max(12, Math.min(growthSize * dpr, maxDrawableSize));
    const minX = edgeSafeSize / 2 + 16 * dpr;
    const maxX = Math.max(minX, w - edgeSafeSize / 2 - 16 * dpr);
    const minY = edgeSafeSize / 2 + 16 * dpr;
    const maxY = Math.max(minY, h - edgeSafeSize / 2 - 16 * dpr);
    const now = (window.performance && performance.now) ? performance.now() : Date.now();

    if (!state.x || !state.y || state.x < minX || state.x > maxX || state.y < minY || state.y > maxY) {
        state.x = Math.min(maxX, Math.max(minX, w / 2));
        state.y = Math.min(maxY, Math.max(minY, h * 0.55));
        if (window.pickMeowlimeGrowthTarget) window.pickMeowlimeGrowthTarget(state, w, h, edgeSafeSize, dpr);
    }

    if (!state.targetX || !state.targetY) {
        if (window.pickMeowlimeGrowthTarget) window.pickMeowlimeGrowthTarget(state, w, h, edgeSafeSize, dpr);
    }

    const blockedByTouch = !!state.isPointerDown || !!state.isHolding || !!state.dragging || (state.releaseBounceUntil && now < state.releaseBounceUntil);

    if (!blockedByTouch) {
        const tx = Math.min(maxX, Math.max(minX, state.targetX || state.x));
        const ty = Math.min(maxY, Math.max(minY, state.targetY || state.y));
        const dx = tx - state.x;
        const dy = ty - state.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < Math.max(8 * dpr, edgeSafeSize * 0.14) || now > Number(state.nextTargetAt || 0)) {
            if (window.pickMeowlimeGrowthTarget) window.pickMeowlimeGrowthTarget(state, w, h, edgeSafeSize, dpr);
        } else {
            const glide = Math.min(1, dt * (0.58 + Math.min(0.5, dist / Math.max(1, Math.max(w, h)))));
            state.x += dx * glide;
            state.y += dy * glide;
        }
    }

    state.x = Math.min(maxX, Math.max(minX, state.x));
    state.y = Math.min(maxY, Math.max(minY, state.y));

    const dragLen = Math.sqrt((state.dragDX || 0) * (state.dragDX || 0) + (state.dragDY || 0) * (state.dragDY || 0));
    const maxStretch = Math.max(24 * dpr, edgeSafeSize * 0.92);
    const targetStretch = state.isHolding && state.dragging
        ? Math.min(0.72, dragLen / Math.max(1, maxStretch) * 0.72)
        : 0;

    if (state.isHolding && state.dragging && dragLen > 0.5) {
        state.stretchAngle = Math.atan2(state.dragDY, state.dragDX);
    }

    state.stretchPower += (targetStretch - (state.stretchPower || 0)) * Math.min(1, dt * 14);
    if (!state.isHolding && Math.abs(state.stretchPower) < 0.002) state.stretchPower = 0;

    let jigglePower = state.jiggleUntil && now < state.jiggleUntil
        ? Math.max(0, (state.jiggleUntil - now) / 620)
        : 0;

    if (state.releaseBounceUntil && now < state.releaseBounceUntil) {
        jigglePower = Math.max(jigglePower, Math.max(0, (state.releaseBounceUntil - now) / 760));
    }

    let touchGlow = 0;
    if (state.touchPulseUntil && now < state.touchPulseUntil) {
        const full = Math.max(1, state.touchPulseUntil - Number(state.touchPulseStart || now));
        touchGlow = Math.max(0, Math.min(1, (state.touchPulseUntil - now) / full));
    }

    const floatPower = blockedByTouch ? 0.18 : 1;
    const drawX = state.x + Math.sin(ts / 1000 * 1.8 + state.floatSeed) * 4 * dpr * floatPower;
    const drawY = state.y + Math.cos(ts / 1000 * 2.15 + state.floatSeed * 0.7) * 7 * dpr * floatPower;

    window.drawMeowlimeGrowthBackground(ctx, w, h, ts / 1000);
    window.drawMeowlimeGrowthBlob(ctx, drawX, drawY, edgeSafeSize, state.expression, ts / 1000, jigglePower, {
        stretchPower: state.stretchPower || 0,
        stretchAngle: state.stretchAngle || 0,
        touchGlow: touchGlow,
        hueShift: state.touchHueShift || 0
    });

    state.rafId = requestAnimationFrame(window.renderMeowlimeGrowthFrame);
};

window.startMeowlimeGrowthCanvas = function() {
    const modal = document.getElementById('meowlime-growth-modal');
    const canvas = document.getElementById('meowlime-growth-canvas');
    const totalEl = document.getElementById('meowlime-growth-total-text');
    const sizeEl = document.getElementById('meowlime-growth-size-text');

    if (!modal || !canvas) return;

    window.stopMeowlimeGrowthCanvas();

    const state = window.getMeowlimeGrowthState();
    const growthSize = window.getMeowlimeGrowthSize ? window.getMeowlimeGrowthSize() : 20;
    const total = Number((window.GameLogic && window.GameLogic.dailyMeowlime && window.GameLogic.dailyMeowlime.totalCheckins) || 0);

    state.running = true;
    state.lastTs = 0;
    state.x = 0;
    state.y = 0;
    state.targetX = 0;
    state.targetY = 0;
    state.nextTargetAt = 0;
    state.floatSeed = Math.random() * 1000;
    state.expression = '^⦁⩊⦁^';
    state.jiggleUntil = 0;
    state.touchPulseUntil = 0;
    state.touchPulseStart = 0;
    state.touchHueShift = 0;
    state.stretchPower = 0;
    state.stretchAngle = 0;
    state.dragDX = 0;
    state.dragDY = 0;
    state.pointerId = null;
    state.isPointerDown = false;
    state.isHolding = false;
    state.dragging = false;
    state.releaseBounceUntil = 0;

    if (state.holdTimer) {
        clearTimeout(state.holdTimer);
        state.holdTimer = null;
    }

    if (totalEl) totalEl.innerText = String(Number.isFinite(total) ? Math.max(0, total) : 0);
    if (sizeEl) sizeEl.innerText = `${growthSize.toFixed(1)}px`;

    const stopModalEvent = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();
    };

    const beginTouchReaction = () => {
        const pool = window.getMeowlimeGrowthExpressions ? window.getMeowlimeGrowthExpressions() : ['^⦁⩊⦁^'];
        state.expression = pool[Math.floor(Math.random() * pool.length)] || '^⦁⩊⦁^';
        state.jiggleUntil = performance.now() + 620;
        state.touchPulseStart = performance.now();
        state.touchPulseUntil = state.touchPulseStart + 520;
        state.touchHueShift = Math.random() * 360;

        if (window.playMeowlimeSFX) {
            window.playMeowlimeSFX('catslime-sign-touch', {
                cooldownKey: 'catslime-sign-touch',
                cooldownMs: 280
            });
        }
    };

    const pointerHandler = (e) => {
        if (!e) return;
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();

        if (state.isPointerDown) return;

        window.resizeMeowlimeGrowthCanvas(canvas);

        const point = window.getMeowlimeGrowthPointerPoint
            ? window.getMeowlimeGrowthPointerPoint(canvas, e)
            : { x: 0, y: 0 };
        const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
        const size = Math.max(12, Math.min((window.getMeowlimeGrowthSize ? window.getMeowlimeGrowthSize() : 20) * dpr, Math.max(12, Math.min(canvas.width, canvas.height) - 36 * dpr)));
        const dx = point.x - state.x;
        const dy = point.y - state.y;

        if (Math.sqrt(dx * dx + dy * dy) > size * 0.72) return;

        if (canvas.setPointerCapture && e.pointerId !== undefined) {
            try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
        }

        state.pointerId = e.pointerId;
        state.pointerDownAt = performance.now();
        state.pointerStartX = point.x;
        state.pointerStartY = point.y;
        state.isPointerDown = true;
        state.isHolding = false;
        state.dragging = false;
        state.dragDX = 0;
        state.dragDY = 0;
        state.releaseBounceUntil = 0;

        beginTouchReaction();

        if (state.holdTimer) clearTimeout(state.holdTimer);
        state.holdTimer = setTimeout(() => {
            state.holdTimer = null;
            if (!state.running || !state.isPointerDown) return;

            state.isHolding = true;
            state.dragging = false;
            state.dragDX = 0;
            state.dragDY = 0;
            state.jiggleUntil = performance.now() + 360;
        }, 320);
    };

    const pointerMoveHandler = (e) => {
        if (!e || !state.isPointerDown) return;
        if (state.pointerId !== null && e.pointerId !== undefined && e.pointerId !== state.pointerId) return;

        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();

        const point = window.getMeowlimeGrowthPointerPoint
            ? window.getMeowlimeGrowthPointerPoint(canvas, e)
            : { x: state.pointerStartX, y: state.pointerStartY };
        const dpr = Math.max(1, Math.min(2, window.devicePixelRatio || 1));
        const size = Math.max(12, Math.min((window.getMeowlimeGrowthSize ? window.getMeowlimeGrowthSize() : 20) * dpr, Math.max(12, Math.min(canvas.width, canvas.height) - 36 * dpr)));
        const rawDX = point.x - state.pointerStartX;
        const rawDY = point.y - state.pointerStartY;
        const rawDist = Math.sqrt(rawDX * rawDX + rawDY * rawDY);
        const maxStretch = Math.max(24 * dpr, size * 0.92);
        const limitRate = rawDist > maxStretch ? maxStretch / rawDist : 1;

        if (!state.isHolding) {
            return;
        }

        state.dragging = rawDist > 1 * dpr;
        state.dragDX = state.dragging ? rawDX * limitRate : 0;
        state.dragDY = state.dragging ? rawDY * limitRate : 0;
    };

    const endTouch = (e) => {
        if (!state.isPointerDown && !state.isHolding && !state.dragging) return;

        const activePointerId = state.pointerId;
        if (e && activePointerId !== null && e.pointerId !== undefined && e.pointerId !== activePointerId) return;

        if (e && e.preventDefault) e.preventDefault();
        if (e && e.stopPropagation) e.stopPropagation();

        const wasHolding = !!state.isHolding;
        const wasDragging = !!state.dragging;

        if (state.holdTimer) {
            clearTimeout(state.holdTimer);
            state.holdTimer = null;
        }

        if (canvas.releasePointerCapture && activePointerId !== null && activePointerId !== undefined) {
            try { canvas.releasePointerCapture(activePointerId); } catch (_) {}
        }

        if (wasHolding || wasDragging) {
            state.releaseBounceUntil = performance.now() + 760;
            state.jiggleUntil = performance.now() + 760;
        }

        state.pointerId = null;
        state.pointerDownAt = 0;
        state.pointerStartX = 0;
        state.pointerStartY = 0;
        state.isPointerDown = false;
        state.isHolding = false;
        state.dragging = false;
        state.dragDX = 0;
        state.dragDY = 0;
    };

    const resizeHandler = () => {
        state.x = 0;
        state.targetX = 0;
        state.targetY = 0;
        if (window.resizeMeowlimeGrowthCanvas) window.resizeMeowlimeGrowthCanvas(canvas);
    };

    modal.addEventListener('pointerdown', stopModalEvent);
    modal.addEventListener('click', stopModalEvent);
    canvas.addEventListener('pointerdown', pointerHandler, { passive: false });
    canvas.addEventListener('pointerleave', endTouch, { passive: false });
    canvas.addEventListener('lostpointercapture', endTouch, { passive: false });
    window.addEventListener('pointermove', pointerMoveHandler, { passive: false });
    window.addEventListener('pointerup', endTouch, { passive: false });
    window.addEventListener('pointercancel', endTouch, { passive: false });
    window.addEventListener('mouseup', endTouch, { passive: false });
    window.addEventListener('resize', resizeHandler);

    state.boundCanvas = canvas;
    state.boundModal = modal;
    state.pointerHandler = pointerHandler;
    state.pointerMoveHandler = pointerMoveHandler;
    state.pointerUpHandler = endTouch;
    state.pointerCancelHandler = endTouch;
    state.pointerLeaveHandler = endTouch;
    state.lostPointerCaptureHandler = endTouch;
    state.mouseUpHandler = endTouch;
    state.modalStopHandler = stopModalEvent;
    state.resizeHandler = resizeHandler;

    canvas.style.touchAction = 'none';
    window.resizeMeowlimeGrowthCanvas(canvas);
    state.rafId = requestAnimationFrame(window.renderMeowlimeGrowthFrame);
};

window.getMeowlimeCheckinHistoryList = function() {
    const history = (window.GameLogic && window.GameLogic.dailyMeowlime && window.GameLogic.dailyMeowlime.checkinHistory) || {};
    if (!history || typeof history !== 'object') return [];

    return Object.keys(history)
        .map((dateKey) => {
            const item = history[dateKey] || {};
            const signatureUrl = item.signatureUrl ? String(item.signatureUrl) : '';
            const signaturePath = item.signaturePath ? String(item.signaturePath) : '';

            return {
                date: String(item.date || dateKey || ''),
                createdAt: Number(item.createdAt || 0),
                serverRoom: String(item.serverRoom || ''),
                hasSignature: !!item.hasSignature,
                signatureUrl: signatureUrl,
                signaturePath: signaturePath
            };
        })
        .filter(item => !!item.date)
        .sort((a, b) => {
            if (a.date === b.date) return a.createdAt - b.createdAt;
            return a.date.localeCompare(b.date);
        });
};

window.getMeowlimeStarRoomName = function(roomId) {
    const safeRoomId = roomId ? String(roomId) : '';
    const rooms = (window.GameLogic && window.GameLogic.serverRooms) || {};
    if (safeRoomId && rooms[safeRoomId] && rooms[safeRoomId].name) return rooms[safeRoomId].name;
    return safeRoomId || '未知房間';
};

window.showMeowlimeStarMapMessage = function(message) {
    const panel = document.getElementById('meowlime-star-map-panel');
    const summary = panel ? panel.querySelector('.meowlime-star-map-summary') : null;
    const safeMessage = message || '這顆星星沒有保存簽名圖喵。';

    if (summary) {
        summary.textContent = safeMessage;
        summary.classList.add('meowlime-star-map-summary-flash');

        clearTimeout(window.__meowlimeStarMapMessageTimer);
        window.__meowlimeStarMapMessageTimer = setTimeout(() => {
            if (summary) summary.classList.remove('meowlime-star-map-summary-flash');
            if (window.renderMeowlimeStarMap) window.renderMeowlimeStarMap();
        }, 1600);
        return;
    }

    const errorEl = document.getElementById('meowlime-error-text');
    if (errorEl) errorEl.innerText = safeMessage;
};

window.openMeowlimeSignatureViewer = function(item) {
    const data = item || {};
    const url = data.signatureUrl ? String(data.signatureUrl) : '';

    if (!url) {
        if (window.showMeowlimeStarMapMessage) window.showMeowlimeStarMapMessage('這顆星星沒有保存簽名圖喵。');
        return;
    }

    const modal = document.getElementById('meowlime-signature-viewer-modal');
    const dateEl = document.getElementById('meowlime-signature-viewer-date');
    const roomEl = document.getElementById('meowlime-signature-viewer-room');
    const img = document.getElementById('meowlime-signature-viewer-img');
    const statusEl = document.getElementById('meowlime-signature-viewer-status');

    if (!modal || !img) {
        console.warn('[喵萊姆] 找不到簽名回放視窗 DOM。');
        return;
    }

    const roomName = window.getMeowlimeStarRoomName
        ? window.getMeowlimeStarRoomName(data.serverRoom)
        : (data.serverRoom || '未知房間');

    if (dateEl) dateEl.innerText = data.date ? `日期：${data.date}` : '日期：未知';
    if (roomEl) roomEl.innerText = `房間：${roomName}`;
    if (statusEl) statusEl.innerText = '簽名圖讀取中……';

    img.onload = () => {
        if (statusEl) statusEl.innerText = '';
    };
    img.onerror = () => {
        console.warn('[喵萊姆] 簽名圖讀取失敗：', url);
        if (statusEl) statusEl.innerText = '簽名圖讀取失敗喵。';
        img.removeAttribute('src');
    };

    img.alt = `${data.date || '某一天'} 的喵萊姆簽名`;
    img.src = url;

    if (window.playMeowlimeModalFadeIn) window.playMeowlimeModalFadeIn(modal);
    else modal.style.display = 'block';
};

window.closeMeowlimeSignatureViewer = function() {
    const modal = document.getElementById('meowlime-signature-viewer-modal');
    const img = document.getElementById('meowlime-signature-viewer-img');
    const statusEl = document.getElementById('meowlime-signature-viewer-status');

    const cleanup = () => {
        if (img) {
            img.onload = null;
            img.onerror = null;
            img.removeAttribute('src');
            img.alt = '';
        }
        if (statusEl) statusEl.innerText = '';
    };

    if (window.closeMeowlimeModalWithFade) window.closeMeowlimeModalWithFade(modal, { afterClose: cleanup });
    else {
        if (modal) modal.style.display = 'none';
        cleanup();
    }
};

window.renderMeowlimeStarMap = function() {
    const panel = document.getElementById('meowlime-star-map-panel');
    if (!panel) return;

    const list = window.getMeowlimeCheckinHistoryList ? window.getMeowlimeCheckinHistoryList() : [];
    const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
    const total = Number((window.GameLogic && window.GameLogic.dailyMeowlime && window.GameLogic.dailyMeowlime.totalCheckins) || list.length || 0);

    panel.innerHTML = '';

    const summary = document.createElement('div');
    summary.className = 'meowlime-star-map-summary';
    summary.textContent = list.length > 0
        ? `已點亮 ${list.length} 顆簽到星星｜累積 ${Math.max(total, list.length)} 天`
        : '還沒有簽到星星，完成一次每日簽到後就會在這裡點亮喵。';
    panel.appendChild(summary);

    const sky = document.createElement('div');
    sky.className = 'meowlime-star-map-sky';
    panel.appendChild(sky);

    const constellationGlow = document.createElement('div');
    constellationGlow.className = 'meowlime-star-map-core';
    sky.appendChild(constellationGlow);

    if (list.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'meowlime-star-map-empty';
        empty.textContent = '尚未有星星資料';
        sky.appendChild(empty);
        return;
    }

    const detailList = document.createElement('div');
    detailList.className = 'meowlime-star-map-list';

    list.forEach((item, idx) => {
        const dayNo = idx + 1;
        const isToday = item.date === today;
        const canViewSignature = !!(item.hasSignature && item.signatureUrl);
        const angle = (idx * 137.5) * Math.PI / 180;
        const ring = 18 + (idx % 5) * 8 + Math.floor(idx / 5) * 2;
        const left = Math.max(10, Math.min(90, 50 + Math.cos(angle) * ring));
        const top = Math.max(12, Math.min(88, 50 + Math.sin(angle) * ring * 0.72));
        const hue = (185 + idx * 43) % 360;
        const roomName = window.getMeowlimeStarRoomName ? window.getMeowlimeStarRoomName(item.serverRoom) : (item.serverRoom || '未知房間');

        const star = document.createElement('div');
        star.className = `meowlime-star-node${isToday ? ' today' : ''}${canViewSignature ? ' has-signature' : ''}`;
        star.style.setProperty('--star-left', `${left}%`);
        star.style.setProperty('--star-top', `${top}%`);
        star.style.setProperty('--star-hue', String(hue));
        star.title = `${item.date}｜第 ${dayNo} 天｜${roomName}${canViewSignature ? '｜點擊查看簽名' : '｜沒有保存簽名圖'}`;
        star.textContent = '✦';
        star.setAttribute('role', 'button');
        star.setAttribute('tabindex', '0');
        star.setAttribute('aria-label', canViewSignature
            ? `${item.date} 第 ${dayNo} 天，點擊查看簽名`
            : `${item.date} 第 ${dayNo} 天，沒有保存簽名圖`);

        let pointerStart = null;

        const handleStarActivate = (e) => {
            if (e && e.stopPropagation) e.stopPropagation();

            if (canViewSignature) {
                if (window.openMeowlimeSignatureViewer) window.openMeowlimeSignatureViewer(item);
            } else if (window.showMeowlimeStarMapMessage) {
                window.showMeowlimeStarMapMessage('這顆星星沒有保存簽名圖喵。');
            }
        };

        star.addEventListener('pointerdown', (e) => {
            if (e && e.stopPropagation) e.stopPropagation();
            pointerStart = e ? { x: e.clientX, y: e.clientY, t: Date.now() } : null;
        }, { passive: true });

        star.addEventListener('pointerup', (e) => {
            if (e && e.stopPropagation) e.stopPropagation();

            if (pointerStart && e) {
                const dx = Math.abs(e.clientX - pointerStart.x);
                const dy = Math.abs(e.clientY - pointerStart.y);
                if (dx > 8 || dy > 8) {
                    pointerStart = null;
                    return;
                }
            }

            pointerStart = null;
            handleStarActivate(e);
        }, { passive: true });

        star.addEventListener('click', (e) => {
            if (e && e.stopPropagation) e.stopPropagation();
        });

        star.addEventListener('keydown', (e) => {
            if (!e || (e.key !== 'Enter' && e.key !== ' ')) return;
            e.preventDefault();
            handleStarActivate(e);
        });

        sky.appendChild(star);

        const card = document.createElement('div');
        card.className = `meowlime-star-map-card${isToday ? ' today' : ''}${canViewSignature ? ' has-signature' : ''}`;

        const title = document.createElement('div');
        title.className = 'meowlime-star-map-card-title';
        title.textContent = isToday ? `今日星星｜第 ${dayNo} 天` : `第 ${dayNo} 天`;

        const meta = document.createElement('div');
        meta.className = 'meowlime-star-map-card-meta';
        meta.textContent = `${item.date}｜${roomName}${canViewSignature ? '｜已保存簽名圖' : '｜無簽名圖'}`;

        card.appendChild(title);
        card.appendChild(meta);
        detailList.appendChild(card);
    });

    panel.appendChild(detailList);
};

window.setMeowlimeGrowthTab = function(tabName = 'growth') {
    const activeTab = tabName === 'map' ? 'map' : 'growth';
    const growthPanel = document.getElementById('meowlime-growth-panel');
    const mapPanel = document.getElementById('meowlime-star-map-panel');
    const growthBtn = document.getElementById('meowlime-growth-tab-capsule');
    const mapBtn = document.getElementById('meowlime-growth-tab-map');

    if (growthBtn) growthBtn.classList.toggle('active', activeTab === 'growth');
    if (mapBtn) mapBtn.classList.toggle('active', activeTab === 'map');

    if (growthPanel) {
        growthPanel.classList.remove('meowlime-panel-fade-in');
        growthPanel.hidden = activeTab !== 'growth';
    }
    if (mapPanel) {
        mapPanel.classList.remove('meowlime-panel-fade-in');
        mapPanel.hidden = activeTab !== 'map';
    }

    const activePanel = activeTab === 'growth' ? growthPanel : mapPanel;
    if (activePanel) {
        void activePanel.offsetWidth;
        activePanel.classList.add('meowlime-panel-fade-in');
        clearTimeout(activePanel.__meowlimePanelFadeTimer);
        activePanel.__meowlimePanelFadeTimer = setTimeout(() => {
            if (activePanel) activePanel.classList.remove('meowlime-panel-fade-in');
        }, 280);
    }

    if (activeTab === 'growth') {
        if (window.startMeowlimeGrowthCanvas) window.startMeowlimeGrowthCanvas();
    } else {
        if (window.stopMeowlimeGrowthCanvas) window.stopMeowlimeGrowthCanvas();
        if (window.renderMeowlimeStarMap) window.renderMeowlimeStarMap();
    }
};


window.openMeowlimeGrowthModal = async function() {
    if (window.refreshDailyMeowlimeStatus) {
        await window.refreshDailyMeowlimeStatus({ reason: 'openMeowlimeGrowthModal', skipIfFresh: true });
    }

    const checkinModal = document.getElementById('meowlime-modal');
    const growthModal = document.getElementById('meowlime-growth-modal');

    const openGrowth = () => {
        if (window.playMeowlimeModalFadeIn) window.playMeowlimeModalFadeIn(growthModal);
        else if (growthModal) growthModal.style.display = 'block';

        if (window.setMeowlimeGrowthTab) {
            window.setMeowlimeGrowthTab('growth');
        } else if (window.startMeowlimeGrowthCanvas) {
            window.startMeowlimeGrowthCanvas();
        }
    };

    if (checkinModal && checkinModal.style.display !== 'none') {
        if (window.closeMeowlimeModalWithFade) {
            window.closeMeowlimeModalWithFade(checkinModal, { duration: 200, afterClose: openGrowth });
        } else {
            checkinModal.style.display = 'none';
            openGrowth();
        }
    } else {
        openGrowth();
    }
};
window.closeMeowlimeGrowthModal = function(options = {}) {
    const shouldReturnToCheckin = options.returnToCheckin !== false;
    const growthModal = document.getElementById('meowlime-growth-modal');
    const checkinModal = document.getElementById('meowlime-modal');

    if (window.stopMeowlimeGrowthCanvas) window.stopMeowlimeGrowthCanvas();

    const afterClose = () => {
        if (shouldReturnToCheckin && checkinModal) {
            if (window.playMeowlimeModalFadeIn) window.playMeowlimeModalFadeIn(checkinModal);
            else checkinModal.style.display = 'block';
            if (window.prepareMeowlimeCheckinModal) window.prepareMeowlimeCheckinModal();
            if (window.updateMeowlimeModalStatusText) window.updateMeowlimeModalStatusText();
        }
    };

    if (window.closeMeowlimeModalWithFade) window.closeMeowlimeModalWithFade(growthModal, { afterClose });
    else {
        if (growthModal) growthModal.style.display = 'none';
        afterClose();
    }
};

window.getMeowlimeCatalogIconHtml = function() {
    try {
        const scene = window.GameLogic && window.GameLogic.phaserGame
            ? window.GameLogic.phaserGame.scene.getScene('MainScene')
            : null;
        const src = scene && scene.getMeowlimeCatalogIconDataUrl ? scene.getMeowlimeCatalogIconDataUrl() : '';
        if (src) {
            return `<img class="meowlime-catalog-phaser-img" src="${src}" alt="喵萊姆">`;
        }
    } catch (err) {
        console.warn('[喵萊姆] 目錄縮圖產生失敗，改用 DOM 備援：', err);
    }

    return `<div class="meowlime-catalog-icon"><span>^⦁⩊⦁^</span></div>`;
};

window.getMeowlimeTodayDateString = function(date = new Date()) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

window.applyMeowlimeDailyState = function(data = {}) {
    if (!window.GameLogic) return;

    const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
    const dailyData = data || {};
    const lastCheckinDate = dailyData.lastCheckinDate ? String(dailyData.lastCheckinDate) : '';

    window.GameLogic.dailyMeowlime = {
        lastCheckinDate: lastCheckinDate,
        totalCheckins: Number(dailyData.totalCheckins || 0),
        checkinHistory: dailyData.checkinHistory || {}
    };
    window.GameLogic.meowlimeDailyDate = today;
    window.GameLogic.meowlimeDailyLoaded = true;
    window.GameLogic.meowlimeCanCheckinToday = lastCheckinDate !== today;

    if (window.updateMeowlimeModalStatusText) window.updateMeowlimeModalStatusText();
    if (window.refreshMeowlimeVisualsInScene) window.refreshMeowlimeVisualsInScene();
    if (window.renderMeowlimeStarMap) window.renderMeowlimeStarMap();
};

window.updateMeowlimeModalStatusText = function() {
    if (window.renderMeowlimeCheckinModal) {
        window.renderMeowlimeCheckinModal();
        return;
    }

    const textEl = document.querySelector('#meowlime-modal .meowlime-modal-text');
    if (!textEl || !window.GameLogic) return;

    if (!window.GameLogic.meowlimeDailyLoaded) {
        textEl.innerText = '喵萊姆正在確認今日簽到狀態……';
        return;
    }

    textEl.innerText = window.GameLogic.meowlimeCanCheckinToday
        ? '喵萊姆：今天還沒簽到喵。'
        : '喵萊姆：今天已經簽到過囉，明天再來喵。';
};

window.refreshMeowlimeVisualsInScene = function() {
    try {
        const scene = window.GameLogic && window.GameLogic.phaserGame
            ? window.GameLogic.phaserGame.scene.getScene('MainScene')
            : null;
        if (scene && scene.refreshMeowlimeDailyHintVisuals) {
            scene.refreshMeowlimeDailyHintVisuals();
        }
    } catch (err) {
        console.warn('[喵萊姆] 刷新大廳提示失敗：', err);
    }
};

window.refreshDailyMeowlimeStatus = async function(options = {}) {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return null;

    const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
    const now = Date.now();

    if (
        options.skipIfFresh &&
        window.GameLogic.meowlimeDailyLoaded &&
        window.GameLogic.meowlimeDailyDate === today &&
        window.__meowlimeDailyLastFetchedAt &&
        now - window.__meowlimeDailyLastFetchedAt < 180000
    ) {
        return window.GameLogic.dailyMeowlime || null;
    }

    if (window.GameLogic.meowlimeDailyRefreshing) return window.GameLogic.dailyMeowlime || null;

    window.GameLogic.meowlimeDailyRefreshing = true;

    try {
        const uid = window.GameLogic.currentUser.uid;
        const snap = await get(ref(window.GameLogic.db, `users/${uid}/dailyMeowlime`));
        const data = snap.exists() ? (snap.val() || {}) : {};
        window.__meowlimeDailyLastFetchedAt = Date.now();
        window.applyMeowlimeDailyState(data);
        return data;
    } catch (err) {
        console.warn('[喵萊姆] 讀取每日簽到狀態失敗：', err);
        return null;
    } finally {
        window.GameLogic.meowlimeDailyRefreshing = false;
    }
};

window.getMeowlimeSignatureBlob = function() {
    return new Promise((resolve) => {
        try {
            const canvas = document.getElementById('meowlime-signature-canvas');
            const state = window.getMeowlimeSignatureState ? window.getMeowlimeSignatureState() : null;

            if (!canvas) {
                resolve({ ok: false, reason: 'missing-canvas' });
                return;
            }

            if (!state || !state.hasInk) {
                resolve({ ok: false, reason: 'no-ink' });
                return;
            }

            if (typeof canvas.toBlob !== 'function') {
                resolve({ ok: false, reason: 'toBlob-unavailable' });
                return;
            }

            canvas.toBlob((blob) => {
                if (!blob || blob.size <= 0) {
                    resolve({ ok: false, reason: 'empty-blob' });
                    return;
                }

                resolve({ ok: true, blob: blob });
            }, 'image/png');
        } catch (err) {
            console.warn('[喵萊姆] 簽名圖轉 Blob 失敗：', err);
            resolve({ ok: false, reason: 'blob-error' });
        }
    });
};

window.uploadMeowlimeSignatureImage = async function(dateKey) {
    try {
        if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.currentUser.uid) {
            return { ok: false, reason: 'no-user' };
        }

        const activeStorage = (window.GameLogic && window.GameLogic.storage) || (typeof storage !== 'undefined' ? storage : null);
        if (!activeStorage) {
            return { ok: false, reason: 'missing-storage' };
        }

        if (typeof storageRef !== 'function' || typeof uploadBytes !== 'function' || typeof getDownloadURL !== 'function') {
            return { ok: false, reason: 'storage-sdk-unavailable' };
        }

        if (!window.getMeowlimeSignatureBlob) {
            return { ok: false, reason: 'missing-blob-helper' };
        }

        const blobResult = await window.getMeowlimeSignatureBlob();
        if (!blobResult || !blobResult.ok || !blobResult.blob) {
            return { ok: false, reason: blobResult && blobResult.reason ? blobResult.reason : 'blob-failed' };
        }

        const uid = window.GameLogic.currentUser.uid;
        const safeDateKey = String(dateKey || (window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : ''))
            .replace(/[^\d-]/g, '');

        if (!safeDateKey) {
            return { ok: false, reason: 'missing-date' };
        }

        const storagePath = `users/${uid}/dailyMeowlimeSignatures/${safeDateKey}.png`;
        const imageRef = storageRef(activeStorage, storagePath);

        await uploadBytes(imageRef, blobResult.blob, { contentType: 'image/png' });
        const downloadUrl = await getDownloadURL(imageRef);

        return {
            ok: true,
            signatureUrl: downloadUrl,
            signaturePath: storagePath
        };
    } catch (err) {
        console.warn('[喵萊姆] 簽名圖上傳失敗：', err);
        return {
            ok: false,
            reason: err && err.code ? err.code : 'upload-error'
        };
    }
};

window.recordDailyMeowlimeCheckin = async function(signatureInfo = {}) {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return { ok: false, reason: 'no-user' };

    const uid = window.GameLogic.currentUser.uid;
    const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
    const rewardCoins = 888;
    const signatureUrl = signatureInfo && signatureInfo.signatureUrl ? String(signatureInfo.signatureUrl) : '';
    const signaturePath = signatureInfo && signatureInfo.signaturePath ? String(signatureInfo.signaturePath) : '';
    const checkinRequestId = `${today}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const createdAt = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();
    let txResult = null;

    try {
        txResult = await runTransaction(ref(window.GameLogic.db, `users/${uid}`), (userData) => {
            if (!userData || typeof userData !== 'object') userData = {};

            const dailyData = userData.dailyMeowlime && typeof userData.dailyMeowlime === 'object'
                ? userData.dailyMeowlime
                : {};
            const history = dailyData.checkinHistory && typeof dailyData.checkinHistory === 'object'
                ? dailyData.checkinHistory
                : {};
            const todayHistory = history[today] && typeof history[today] === 'object'
                ? history[today]
                : {};

            if (dailyData.lastCheckinDate === today || todayHistory.rewardClaimed === true) {
                return userData;
            }

            const totalCheckins = Number(dailyData.totalCheckins || 0) + 1;
            const historyItem = {
                date: today,
                createdAt: createdAt,
                serverRoom: window.getCurrentServerRoomId ? window.getCurrentServerRoomId() : (window.GameLogic.currentServerRoom || ''),
                hasSignature: !!signatureUrl,
                rewardCoins: rewardCoins,
                rewardClaimed: true,
                checkinRequestId: checkinRequestId
            };

            if (signatureUrl) {
                historyItem.signatureUrl = signatureUrl;
                historyItem.signaturePath = signaturePath;
            }

            userData.coins = Number(userData.coins || 0) + rewardCoins;
            userData.dailyMeowlime = {
                ...dailyData,
                lastCheckinDate: today,
                totalCheckins: totalCheckins,
                checkinHistory: {
                    ...history,
                    [today]: historyItem
                }
            };

            return userData;
        });
    } catch (err) {
        console.warn('[喵萊姆] 每日簽到 transaction 失敗：', err);
        return { ok: false, reason: err && err.code ? err.code : 'transaction-failed' };
    }

    if (!txResult || !txResult.committed) {
        return { ok: false, reason: 'transaction-aborted' };
    }

    const nextUserData = txResult.snapshot && txResult.snapshot.exists && txResult.snapshot.exists() ? (txResult.snapshot.val() || {}) : {};
    const nextDailyData = nextUserData.dailyMeowlime || {};
    const nextHistory = nextDailyData.checkinHistory || {};
    const todayItem = nextHistory[today] || {};
    const rewardClaimedNow = todayItem.checkinRequestId === checkinRequestId && todayItem.rewardClaimed === true;
    const nextCoins = Number(nextUserData.coins || 0);

    window.__meowlimeDailyLastFetchedAt = Date.now();
    window.applyMeowlimeDailyState(nextDailyData);

    if (Number.isFinite(nextCoins)) {
        if (window.syncPlayerCoinsUi) window.syncPlayerCoinsUi(nextCoins);
        else if (window.GameLogic && window.GameLogic.myProfile) window.GameLogic.myProfile.coins = nextCoins;
    }

    return {
        ok: true,
        alreadyChecked: !rewardClaimedNow,
        rewardClaimed: rewardClaimedNow,
        rewardCoins: rewardClaimedNow ? rewardCoins : 0,
        date: today,
        totalCheckins: Number(nextDailyData.totalCheckins || 0),
        coins: nextCoins
    };
};

window.startMeowlimeDailyWatcher = function() {
    if (window.__meowlimeDailyTimer) return;

    window.__meowlimeLastLocalDate = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';

    window.__meowlimeDailyTimer = setInterval(() => {
        const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
        if (!today || today === window.__meowlimeLastLocalDate) return;

        window.__meowlimeLastLocalDate = today;

        if (window.GameLogic) {
            window.GameLogic.meowlimeDailyLoaded = false;
            window.GameLogic.meowlimeDailyDate = today;
            window.GameLogic.meowlimeCanCheckinToday = true;
        }

        if (window.updateMeowlimeModalStatusText) window.updateMeowlimeModalStatusText();
        if (window.refreshMeowlimeVisualsInScene) window.refreshMeowlimeVisualsInScene();
        if (window.refreshDailyMeowlimeStatus) window.refreshDailyMeowlimeStatus({ reason: 'dateChanged' });
    }, 60000);
};

window.stopMeowlimeDailyWatcher = function() {
    if (window.__meowlimeDailyTimer) {
        clearInterval(window.__meowlimeDailyTimer);
        window.__meowlimeDailyTimer = null;
    }
    window.__meowlimeLastLocalDate = null;
    window.__meowlimeDailyLastFetchedAt = 0;
};

window.prepareMeowlimeCheckinModal = function() {
    if (window.initMeowlimeSignatureCanvas) window.initMeowlimeSignatureCanvas();
    if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
};

window.getMeowlimeCheckinDisplayDay = function() {
    const total = Number((window.GameLogic && window.GameLogic.dailyMeowlime && window.GameLogic.dailyMeowlime.totalCheckins) || 0);
    return total;
};

window.getMeowlimeSignatureState = function() {
    if (!window.__meowlimeSignatureState) {
        window.__meowlimeSignatureState = {
            drawing: false,
            hasInk: false,
            pending: false,
            lastX: 0,
            lastY: 0
        };
    }
    return window.__meowlimeSignatureState;
};

window.getMeowlimeCanvasPoint = function(canvas, e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / Math.max(1, rect.width);
    const scaleY = canvas.height / Math.max(1, rect.height);
    return {
        x: (e.clientX - rect.left) * scaleX,
        y: (e.clientY - rect.top) * scaleY
    };
};

window.clearMeowlimeSignature = function() {
    const canvas = document.getElementById('meowlime-signature-canvas');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);

    const state = window.getMeowlimeSignatureState ? window.getMeowlimeSignatureState() : null;
    if (state) state.hasInk = false;

    const errorEl = document.getElementById('meowlime-error-text');
    if (errorEl) errorEl.innerText = '';

    if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
};

window.initMeowlimeSignatureCanvas = function() {
    const canvas = document.getElementById('meowlime-signature-canvas');
    if (!canvas || canvas.dataset.meowlimeBound === '1') return;

    canvas.dataset.meowlimeBound = '1';
    canvas.style.touchAction = 'none';

    const ctx = canvas.getContext('2d');
    if (ctx) {
        ctx.lineWidth = 4;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.strokeStyle = '#dffcff';
        ctx.shadowColor = 'rgba(122, 255, 238, 0.82)';
        ctx.shadowBlur = 8;
    }

    const stopCanvasEvent = (e) => {
        if (!e) return;
        if (e.preventDefault) e.preventDefault();
        if (e.stopPropagation) e.stopPropagation();
    };

    canvas.addEventListener('pointerdown', (e) => {
        stopCanvasEvent(e);

        if (!window.GameLogic || !window.GameLogic.meowlimeDailyLoaded || !window.GameLogic.meowlimeCanCheckinToday) return;

        const state = window.getMeowlimeSignatureState();
        if (state.pending) return;

        const point = window.getMeowlimeCanvasPoint(canvas, e);
        state.drawing = true;
        state.lastX = point.x;
        state.lastY = point.y;

        if (canvas.setPointerCapture && e.pointerId !== undefined) {
            try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
        }

        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.beginPath();
            ctx.moveTo(point.x, point.y);
        }
    }, { passive: false });

    canvas.addEventListener('pointermove', (e) => {
        stopCanvasEvent(e);

        const state = window.getMeowlimeSignatureState();
        if (!state.drawing || state.pending) return;

        const point = window.getMeowlimeCanvasPoint(canvas, e);
        const ctx = canvas.getContext('2d');

        if (ctx) {
            ctx.lineTo(point.x, point.y);
            ctx.stroke();
        }

        state.lastX = point.x;
        state.lastY = point.y;
        state.hasInk = true;

        const errorEl = document.getElementById('meowlime-error-text');
        if (errorEl) errorEl.innerText = '';
    }, { passive: false });

    const endDraw = (e) => {
        stopCanvasEvent(e);
        const state = window.getMeowlimeSignatureState();
        state.drawing = false;
    };

    canvas.addEventListener('pointerup', endDraw, { passive: false });
    canvas.addEventListener('pointercancel', endDraw, { passive: false });
    canvas.addEventListener('pointerleave', endDraw, { passive: false });
};

window.renderMeowlimeCheckinModal = function() {
    const modal = document.getElementById('meowlime-modal');
    if (!modal || !window.GameLogic) return;

    const loaded = !!window.GameLogic.meowlimeDailyLoaded;
    const canCheckin = !!(loaded && window.GameLogic.meowlimeCanCheckinToday);
    const state = window.getMeowlimeSignatureState ? window.getMeowlimeSignatureState() : { hasInk: false, pending: false };
    const signed = loaded && !canCheckin;
    const displayDay = window.getMeowlimeCheckinDisplayDay ? window.getMeowlimeCheckinDisplayDay() : 0;

    const dayEl = document.getElementById('meowlime-day-count');
    const statusEl = document.getElementById('meowlime-status-text');
    const hintEl = document.getElementById('meowlime-signature-hint');
    const wrap = document.getElementById('meowlime-signature-wrap');
    const stamp = document.getElementById('meowlime-stamp');
    const submitBtn = document.getElementById('meowlime-submit-btn');
    const clearBtn = document.getElementById('meowlime-clear-btn');

    if (dayEl) dayEl.innerText = loaded ? String(displayDay) : '確認中';

    if (statusEl) {
        if (!loaded) {
            statusEl.innerText = '喵萊姆正在確認今日簽到狀態……';
        } else if (canCheckin) {
            statusEl.innerText = '喵萊姆：今天還沒簽到喵。';
        } else {
            statusEl.innerText = '今天已經簽到過囉，明天再來喵。';
        }
    }

    if (hintEl) {
        hintEl.innerText = signed ? '今日已簽到完成' : '請在下方簽名欄位留下今天的筆跡';
    }

    if (wrap) {
        wrap.classList.toggle('meowlime-signed', signed);
        wrap.classList.toggle('meowlime-pending', !!state.pending);
    }

    if (stamp) stamp.innerText = '簽到了喵！';

    if (submitBtn) {
        submitBtn.disabled = !loaded || signed || !!state.pending;
        submitBtn.innerText = state.pending ? '簽到中……' : (signed ? '今日已簽到' : '簽到');
        submitBtn.style.display = signed ? 'none' : 'inline-flex';
    }

    if (clearBtn) {
        clearBtn.disabled = !loaded || signed || !!state.pending;
    }
};

window.spawnMeowlimeStampStars = function() {
    const field = document.getElementById('meowlime-star-field');
    if (!field) return;

    field.innerHTML = '';

    for (let i = 0; i < 18; i++) {
        const star = document.createElement('span');
        const angle = Math.random() * Math.PI * 2;
        const dist = 56 + Math.random() * 92;
        star.innerText = '✦';
        star.style.setProperty('--meowlime-star-x', `${Math.cos(angle) * dist}px`);
        star.style.setProperty('--meowlime-star-y', `${Math.sin(angle) * dist}px`);
        star.style.setProperty('--meowlime-star-delay', `${Math.random() * 0.12}s`);
        star.style.setProperty('--meowlime-star-size', `${13 + Math.random() * 12}px`);
        field.appendChild(star);
    }

    setTimeout(() => {
        if (field) field.innerHTML = '';
    }, 900);
};

window.playMeowlimeStampAnimation = function() {
    const wrap = document.getElementById('meowlime-signature-wrap');
    if (!wrap) return;

    wrap.classList.remove('meowlime-stamped');
    void wrap.offsetWidth;
    wrap.classList.add('meowlime-stamped');

    if (window.spawnMeowlimeStampStars) window.spawnMeowlimeStampStars();

    setTimeout(() => {
        if (wrap) wrap.classList.remove('meowlime-stamped');
    }, 980);
};

window.submitMeowlimeCheckin = async function() {
    const state = window.getMeowlimeSignatureState ? window.getMeowlimeSignatureState() : null;
    const errorEl = document.getElementById('meowlime-error-text');

    if (!state) return;
    if (state.pending) return;

    if (errorEl) errorEl.innerText = '';

    try {
        if (window.refreshDailyMeowlimeStatus) {
            await window.refreshDailyMeowlimeStatus({ reason: 'submitMeowlimeCheckin' });
        }

        if (!window.GameLogic || !window.GameLogic.meowlimeDailyLoaded) {
            if (errorEl) errorEl.innerText = '喵萊姆還在確認資料，請再試一次。';
            return;
        }

        if (!window.GameLogic.meowlimeCanCheckinToday) {
            if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
            if (window.playMeowlimeStampAnimation) window.playMeowlimeStampAnimation();
            return;
        }

        if (!state.hasInk) {
            if (errorEl) errorEl.innerText = '請先在簽名欄位留下筆跡喵。';
            return;
        }

        state.pending = true;
        if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();

        const today = window.getMeowlimeTodayDateString ? window.getMeowlimeTodayDateString() : '';
        const signatureInfo = window.uploadMeowlimeSignatureImage
            ? await window.uploadMeowlimeSignatureImage(today)
            : { ok: false, reason: 'missing-upload-helper' };

        if (!signatureInfo || !signatureInfo.ok || !signatureInfo.signatureUrl) {
            console.warn('[喵萊姆] 簽名圖上傳未完成，取消本次簽到：', signatureInfo);
            state.pending = false;
            if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
            if (errorEl) errorEl.innerText = '簽名圖上傳失敗，請稍後再試喵。';
            return;
        }

        const result = window.recordDailyMeowlimeCheckin
            ? await window.recordDailyMeowlimeCheckin(signatureInfo)
            : { ok: false, reason: 'missing-helper' };

        if (!result || !result.ok) {
            throw new Error(result && result.reason ? result.reason : 'checkin-failed');
        }

        state.pending = false;
        if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
        if (!result.alreadyChecked && window.playMeowlimeSFX) window.playMeowlimeSFX('catslime-sign-done');
        if (result.rewardClaimed && window.showMeowlimeRewardToast) {
            window.showMeowlimeRewardToast('簽到獎勵888馬德幣，祝你發發發');
        }
        if (result.rewardClaimed && result.coins !== undefined && window.syncPlayerCoinsUi) {
            window.syncPlayerCoinsUi(result.coins);
        }
        if (window.playMeowlimeStampAnimation) window.playMeowlimeStampAnimation();
        if (window.refreshMeowlimeVisualsInScene) window.refreshMeowlimeVisualsInScene();
    } catch (err) {
        console.warn('[喵萊姆] 簽到失敗：', err);
        state.pending = false;
        if (window.renderMeowlimeCheckinModal) window.renderMeowlimeCheckinModal();
        if (errorEl) errorEl.innerText = '簽到暫時失敗，請稍後再試喵。';
    }
};

// 新增：空間傳送門點擊時的粒子噴發效果

window.popPortalParticles = function(e) {
    const x = e && Number.isFinite(e.clientX) ? e.clientX : window.innerWidth / 2;
    const y = e && Number.isFinite(e.clientY) ? e.clientY : window.innerHeight / 2;

    for (let i = 0; i < 12; i++) {
        const p = document.createElement('div');
        p.style.cssText = `position:fixed; width:6px; height:6px; background:#fff; border-radius:50%; left:${x}px; top:${y}px; pointer-events:none; z-index:9999; transition: all 0.4s cubic-bezier(0.1, 0.8, 0.3, 1); transform: translate(-50%, -50%); box-shadow: 0 0 8px #fff, 0 0 15px #d8bfd8;`;
        document.body.appendChild(p);

        setTimeout(() => {
            const angle = Math.random() * Math.PI * 2;
            const dist = Math.random() * 60 + 20;
            p.style.transform = `translate(calc(-50% + ${Math.cos(angle) * dist}px), calc(-50% + ${Math.sin(angle) * dist}px)) scale(0)`;
            p.style.opacity = 0;
        }, 10);

        setTimeout(() => {
            if (p && p.parentNode) p.parentNode.removeChild(p);
        }, 400);
    }
};

window.popPhoneHeaderParticles = function(e) {
    const target = e && e.currentTarget ? e.currentTarget : (e && e.target ? e.target : null);
    const rect = target && target.getBoundingClientRect ? target.getBoundingClientRect() : null;
    const x = e && Number.isFinite(e.clientX) ? e.clientX : (rect ? rect.left + rect.width / 2 : window.innerWidth - 52);
    const y = e && Number.isFinite(e.clientY) ? e.clientY : (rect ? rect.top + rect.height / 2 : 58);
    const colors = ['#ffffff', '#ff8bd4', '#7fffea', '#fff1a8', '#ff4fa3'];

    for (let i = 0; i < 16; i++) {
        const p = document.createElement('div');
        const size = 4 + Math.random() * 5;
        const color = colors[Math.floor(Math.random() * colors.length)] || '#ffffff';
        const shape = Math.random() > 0.35 ? '50%' : '3px';

        p.style.cssText = `position:fixed; width:${size}px; height:${size}px; left:${x}px; top:${y}px; border-radius:${shape}; background:${color}; pointer-events:none; z-index:9999; opacity:1; transform:translate(-50%, -50%) scale(1); transition:transform 0.42s cubic-bezier(0.12, 0.84, 0.24, 1), opacity 0.42s ease-out; box-shadow:0 0 8px ${color}, 0 0 16px rgba(255,255,255,0.7);`;
        document.body.appendChild(p);

        setTimeout(() => {
            const angle = Math.random() * Math.PI * 2;
            const dist = 26 + Math.random() * 54;
            const spin = -70 + Math.random() * 140;
            p.style.transform = `translate(calc(-50% + ${Math.cos(angle) * dist}px), calc(-50% + ${Math.sin(angle) * dist}px)) rotate(${spin}deg) scale(0)`;
            p.style.opacity = 0;
        }, 12);

        setTimeout(() => {
            if (p && p.parentNode) p.parentNode.removeChild(p);
        }, 520);
    }
};
