window.refreshMobileViewportLayout = function() {

// ====== 猜拳遊戲：手機 PWA 圖層防穿透保護 ======
window.setRpsModalActive = function(isActive) {
    if (!window.GameLogic) return false;

    const active = !!isActive;
    window.GameLogic.rpsModalActive = active;

    try {
        document.body.classList.toggle('rps-modal-active', active);
    } catch (_) {}

    return active;
};

window.syncRpsModalActive = function() {
    const modal = document.getElementById('rps-modal');
    if (!modal) {
        window.setRpsModalActive(false);
        return false;
    }

    const style = window.getComputedStyle(modal);
    const active = style.display !== 'none' && style.visibility !== 'hidden' && Number(style.opacity || 1) !== 0;
    return window.setRpsModalActive(active);
};

window.installRpsModalGuards = function() {
    const modal = document.getElementById('rps-modal');
    if (!modal || modal.__rpsModalGuardsInstalled) return;

    modal.__rpsModalGuardsInstalled = true;
    modal.style.touchAction = 'none';
    modal.style.pointerEvents = 'auto';

    const stopInsideRps = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();

        // 不阻擋 button / img 本身 onclick 或 onpointerdown，只阻止滑動、滾輪、右鍵等穿透與瀏覽器原生行為。
        if (
            e &&
            e.cancelable &&
            (e.type === 'touchmove' || e.type === 'pointermove' || e.type === 'wheel' || e.type === 'contextmenu')
        ) {
            e.preventDefault();
        }
    };

    [
        'pointerdown',
        'pointerup',
        'pointermove',
        'touchstart',
        'touchend',
        'touchmove',
        'mousedown',
        'mouseup',
        'click',
        'dblclick',
        'wheel',
        'contextmenu'
    ].forEach(evt => {
        modal.addEventListener(evt, stopInsideRps, { passive: false });
    });

    const observer = new MutationObserver(() => {
        window.syncRpsModalActive();
    });

    observer.observe(modal, {
        attributes: true,
        attributeFilter: ['style', 'class']
    });

    modal.__rpsModalObserver = observer;
    window.syncRpsModalActive();
};

window.installRpsModalGuards();
// ====== 猜拳遊戲：手機 PWA 圖層防穿透保護結束 ======
  
    try {
        const vv = window.visualViewport;
        const viewW = Math.max(1, Math.round(vv && vv.width ? vv.width : window.innerWidth));
        const viewH = Math.max(1, Math.round(vv && vv.height ? vv.height : window.innerHeight));
        const vh = viewH * 0.01;

        document.documentElement.style.setProperty('--onion-vh', `${vh}px`);

        const appContainer = document.getElementById('app-container');
        const gameLayout = document.getElementById('game-layout-container');
        const phaserApp = document.getElementById('phaser-app');

        [appContainer, gameLayout, phaserApp].forEach(el => {
            if (!el) return;
            el.style.height = `calc(var(--onion-vh, 1vh) * 100)`;
            el.style.minHeight = `calc(var(--onion-vh, 1vh) * 100)`;
        });

        window.scrollTo(0, 0);

        if (window.GameLogic && window.GameLogic.phaserGame && window.GameLogic.phaserGame.scale) {
            const scale = window.GameLogic.phaserGame.scale;

            if (scale.refresh) scale.refresh();
            if (scale.resize) scale.resize(viewW, viewH);

            const uiScene = window.GameLogic.phaserGame.scene.getScene('UIScene');
            if (uiScene && uiScene.resizeUI && uiScene.scale && uiScene.scale.gameSize) {
                uiScene.resizeUI(uiScene.scale.gameSize);
            }

            const mainScene = window.GameLogic.phaserGame.scene.getScene('MainScene');
            if (mainScene && mainScene.updateCameraBounds) {
                mainScene.updateCameraBounds();
            }
        }
    } catch (err) {
        console.warn('[手機版 UI] refreshMobileViewportLayout 失敗，已略過：', err);
    }
};

window.scheduleMobileViewportRefresh = function() {
    try {
        if (window.__onionMobileViewportTimer) clearTimeout(window.__onionMobileViewportTimer);
        window.__onionMobileViewportTimer = setTimeout(() => {
            window.__onionMobileViewportTimer = null;
            if (window.refreshMobileViewportLayout) window.refreshMobileViewportLayout();
        }, 80);
    } catch (_) {}
};

['resize', 'orientationchange', 'pageshow'].forEach(evt => {
    window.addEventListener(evt, window.scheduleMobileViewportRefresh, { passive: true });
});

document.addEventListener('visibilitychange', () => {
    if (!document.hidden && window.scheduleMobileViewportRefresh) {
        window.scheduleMobileViewportRefresh();
    }
});

if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', window.scheduleMobileViewportRefresh, { passive: true });
    window.visualViewport.addEventListener('scroll', window.scheduleMobileViewportRefresh, { passive: true });
}

window.refreshMobileViewportLayout();
window.syncLoginRoomSelect(window.getRememberedServerRoom());

document.body.classList.add('login-bg-active');

window.getPrinceLocalDateKey = function() {
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
};

window.getPrinceBondDesc = function(bond) {
    const val = Number(bond || 0);
    if (val >= 150) return "王子麵覺得你很好笑";
    if (val >= 100) return "王子麵承認你是可疑洋蔥";
    if (val >= 60) return "王子麵開始記得你的毛味";
    if (val >= 30) return "王子麵偶爾聞到你的臭味";
    return "王子麵把你當空氣";
};

window.getPrinceBondEffect = function(bond) {
    const val = Number(bond || 0);
    if (val >= 150) return "效果：掃洋蔥皮時，10% 機率獲得王子麵叼來的 10 馬德幣";
    if (val >= 100) return "效果：掃洋蔥皮時，8% 機率獲得王子麵叼來的 10 馬德幣";
    if (val >= 60) return "效果：掃洋蔥皮時，4% 機率獲得王子麵叼來的 10 馬德幣";
    if (val >= 30) return "效果：掃洋蔥皮時，1% 機率獲得王子麵叼來的 10 馬德幣";
    return "效果：無";
};

window.getPrinceSweepBonusRate = function(bond) {
    const val = Number(bond || 0);
    if (val >= 150) return 0.10;
    if (val >= 100) return 0.08;
    if (val >= 60) return 0.04;
    if (val >= 30) return 0.01;
    return 0;
};

window.getPrinceBondStageIndex = function(bond) {
    const val = Number(bond || 0);
    if (val >= 150) return 4;
    if (val >= 100) return 3;
    if (val >= 60) return 2;
    if (val >= 30) return 1;
    return 0;
};

window.normalizePrinceCatProfileFields = function() {
    const p = window.GameLogic.myProfile || {};
    const today = window.getPrinceLocalDateKey();

    p.princeBond = Number(p.princeBond || 0);
    p.princeRewardsClaimed = p.princeRewardsClaimed || {};

    if (p.princeLastPetDate !== today) {
        p.princePetCountToday = 0;
        p.princeLastPetDate = today;
    } else {
        p.princePetCountToday = Number(p.princePetCountToday || 0);
    }

    if (p.princeLastFeedDate !== today) {
        p.princeFeedCountToday = 0;
        p.princeLastFeedDate = today;
    } else {
        p.princeFeedCountToday = Number(p.princeFeedCountToday || 0);
    }

    window.GameLogic.myProfile = p;
    return p;
};

