window.openInventoryModal = function(options = {}) {
    const list = document.getElementById('inventory-list');
    const hasUnread = Object.keys(window.GameLogic.validUnreadPMs || {}).length > 0;
    const dotHtml = hasUnread ? '<div style="position:absolute; top:5px; right:5px; width:12px; height:12px; background:red; border-radius:50%; box-shadow:0 0 5px red; z-index:10;"></div>' : '';
    let rawItems = {}; let isEdit = window.GameLogic.inventoryEditMode; let inv = window.GameLogic.myProfile.inventory || {}; let sysKeys = ['phone', 'portal', 'profile', 'music', 'app_settings', 'manual', 'logout', 'dev', 'magic_items']; let magicOnlyKeys = ['水球', '煙火', '蔥友機', '派對喇叭', '喵罐頭', '月光碎片', '月光法杖', '月光饅頭']; let keys = Object.keys(inv).filter(k => inv[k] > 0 && k !== '假人洋蔥' && !sysKeys.includes(k) && !magicOnlyKeys.includes(k));
    keys.forEach(k => {
        let iconHtml = (k === '水球') ? '<div class="sprite-waterball"></div>' : (k === '煙火' ? '<img src="shop-fireworks.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;">' : '<span style="font-size:24px; margin-bottom:5px;">📦</span>');
        let isUsing = ((k === '水球' || k === '煙火') && window.GameLogic.armedItemState != null && window.GameLogic.armedItemName === k);
        let itemClass = isUsing ? 'catalog-item item-in-use' : 'catalog-item'; let btnHtml = isUsing ? `<span style="font-size:12px; color:#d9534f; font-weight:bold; margin-top:5px;">[點擊暫停]</span>` : ``; let onclickStr = isUsing ? `window.stopUsingItem('${k}')` : `window.useItem('${k}')`;
        rawItems[k] = `<div class="${itemClass}" style="width: 100%; box-sizing: border-box;" ${!isEdit ? `onclick="${onclickStr}"` : ''}>${iconHtml}<span style="margin:5px 0;">${k} x${inv[k]}</span>${!isEdit ? btnHtml : ''}</div>`;
    });
    rawItems['phone'] = `<div class="catalog-item" style="position:relative; width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'phone\')"' : ''} >${dotHtml}<div class="sprite-onion-phone"></div><span style="margin:5px 0;">洋蔥手機</span></div>`;
    rawItems['portal'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'portal\')"' : ''}><div class="sprite-magic-gap"></div><span style="margin:5px 0;">傳送門</span></div>`;
    rawItems['energy'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'energy\')"' : ''}><img src="sleep-onion-bao.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0;">蔥電飽</span></div>`;
    rawItems['profile'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'profile\')"' : ''}><img src="tools-id-card.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0;">洋蔥身分證</span></div>`;
    rawItems['music'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'music\')"' : ''}><div class="sprite-music-box"></div><span style="margin:5px 0;">蔥Music</span></div>`;
    rawItems['app_settings'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'app_settings\')"' : ''}><span style="font-size:42px; line-height:50px; width:50px; height:50px; margin-bottom:5px; filter:drop-shadow(0 0 8px rgba(255,255,255,0.82));">⚙️</span><span style="margin:5px 0;">設定</span></div>`;
    rawItems['manual'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'manual\')"' : ''}><img src="tools-manual.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0;">說明書</span></div>`;
    rawItems['magic_items'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'magic_items\')"' : ''}><img src="tools-magic-weapon.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0; color:var(--mucha-brown); font-weight:bold;">法寶</span></div>`;
    rawItems['logout'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'logout\')"' : ''}><img src="tools-leave.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0;">登出大廳</span></div>`;if (window.GameLogic.currentUser && window.GameLogic.currentUser.email === 'onion@gmail.com') {
        rawItems['dev'] = `<div class="catalog-item" style="width: 100%; box-sizing: border-box;" ${!isEdit ? 'onclick="window.clickSysItem(\'dev\')"' : ''}><img src="tools-master-onion.png" style="width:50px; height:50px; object-fit:contain; margin-bottom:5px;"><span style="margin:5px 0; font-weight:bold; color:var(--mucha-green);">洋蔥精靈</span></div>`;
    }
    let activeKeys = Object.keys(rawItems); let order = Array.isArray(window.GameLogic.myProfile.inventoryOrder) ? window.GameLogic.myProfile.inventoryOrder.filter(k => k && typeof k === 'string') : []; let finalOrder = order.filter(k => activeKeys.includes(k)); activeKeys.forEach(k => { if (!finalOrder.includes(k)) finalOrder.push(k); }); window.GameLogic.myProfile.inventoryOrder = finalOrder;
    let invHTML = ''; finalOrder.forEach((k, i) => { let inner = rawItems[k]; if (window.GameLogic.inventoryEditMode) { invHTML += `<div style="display:flex; flex-direction:column; align-items:center; background: rgba(0,0,0,0.05); padding: 5px; border-radius: 8px;">${inner}<div style="display:flex; justify-content:space-around; width:100%; margin-top:5px;"><button class="btn-secondary" style="padding:2px 10px;" onclick="window.moveInvItem(${i}, -1)" ${i === 0 ? 'disabled' : ''}>◀</button><button class="btn-secondary" style="padding:2px 10px;" onclick="window.moveInvItem(${i}, 1)" ${i === finalOrder.length - 1 ? 'disabled' : ''}>▶</button></div></div>`; } else { invHTML += inner; } });
    list.style.display = 'grid';
    list.style.gridTemplateColumns = '1fr 1fr';
    list.style.gap = '10px';
    list.style.maxHeight = '60vh';
    list.style.overflowY = 'auto';
    list.style.padding = '5px';
    list.style.alignItems = 'start';
    list.innerHTML = invHTML;

    if (options && options.noFx && window.showInventoryModalWithoutFx) {
        window.showInventoryModalWithoutFx();
    } else if (window.showInventoryModalWithFx) {
        window.showInventoryModalWithFx();
    } else {
        document.getElementById('inventory-modal').style.display = 'block';
    }
};

window.viewOtherProfile = function(uid) { get(ref(window.GameLogic.db, `users/${uid}`)).then(snap => { if (snap.exists()) { document.getElementById('phone-modal').style.display = 'none'; showProfileModal(snap.val(), uid); } }); };

// ====== 好蔥友基礎系統：邀請、接受、拒絕、手機通知 ======
window.getFriendPairId = function(uidA, uidB) {
    return [String(uidA || ''), String(uidB || '')].sort().join('_');
};

window.normalizeFriendRequests = function(rawRequests = {}) {
    const result = {};
    const myUid = window.GameLogic && window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : '';

    if (!rawRequests || typeof rawRequests !== 'object') return result;

    Object.keys(rawRequests).forEach(fromUid => {
        const item = rawRequests[fromUid] || {};
        if (!fromUid || fromUid === myUid) return;
        if (item.status && item.status !== 'pending') return;

        result[fromUid] = {
            fromUid: item.fromUid || fromUid,
            fromName: item.fromName || '匿名洋蔥',
            fromColor: item.fromColor || '#fff',
            createdAt: Number(item.createdAt || 0),
            pairId: item.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, fromUid) : '')
        };
    });

    return result;
};

window.showFriendSystemNotice = function(message) {
    const topBar = document.getElementById('top-notification-bar');
    if (!topBar || !message) return;

    topBar.innerText = `系統通知：${message}`;

    clearTimeout(window.__friendNoticeTimer);
    window.__friendNoticeTimer = setTimeout(() => {
        if (window.updateCurrentRoomLabel) window.updateCurrentRoomLabel();
    }, 2600);
};

window.closeFriendRequestModal = function() {
    const modal = document.getElementById('friend-request-modal');
    if (modal) modal.style.display = 'none';
};

window.showIncomingFriendRequest = function(fromUid, requestData = {}) {
    const modal = document.getElementById('friend-request-modal');
    const nameEl = document.getElementById('friend-request-name');
    if (!modal) return;

    window.__activeFriendRequestUid = fromUid;
    if (nameEl) nameEl.innerText = requestData.fromName || '某顆蔥';
    modal.style.display = 'block';
};

window.startFriendRequestsListener = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    if (friendRequestsUnsubscribe) {
        friendRequestsUnsubscribe();
        friendRequestsUnsubscribe = null;
    }

    friendRequestsUnsubscribe = onValue(ref(window.GameLogic.db, `users/${myUid}/friendRequests`), snap => {
        const requests = window.normalizeFriendRequests ? window.normalizeFriendRequests(snap.val() || {}) : {};
        window.GameLogic.friendRequests = requests;

        const requestUids = Object.keys(requests).sort((a, b) => Number(requests[b].createdAt || 0) - Number(requests[a].createdAt || 0));
        if (requestUids.length > 0) {
            window.showFriendSystemNotice('有蔥想加你好友');
        }

        if (!window.__shownFriendRequestKeys) window.__shownFriendRequestKeys = {};
        const freshUid = requestUids.find(uid => !window.__shownFriendRequestKeys[uid]);
        if (freshUid) {
            window.__shownFriendRequestKeys[freshUid] = true;
            window.showIncomingFriendRequest(freshUid, requests[freshUid]);
        }

        const phoneModal = document.getElementById('phone-modal');
        if (phoneModal && phoneModal.style.display === 'block' && !window.__phoneRendering && window.openPhoneModal) {
            window.openPhoneModal();
        }

        if (profileViewingUid && window.renderProfileFriendButton) {
            window.renderProfileFriendButton(null, profileViewingUid, profileViewingUid === myUid);
        }
    });
};

window.refreshMyFriendsCache = async function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return {};

    try {
        const myUid = window.GameLogic.currentUser.uid;
        const snap = await get(ref(window.GameLogic.db, `users/${myUid}/friends`));
        const friends = snap.val() || {};
        window.GameLogic.friends = friends;

        if (window.refreshFriendPairsCache) {
            window.refreshFriendPairsCache(friends).catch(err => console.warn('[好蔥友] 讀取共同友好度快取失敗：', err));
        }

        return friends;
    } catch (err) {
        console.warn('[好蔥友] 讀取好友列表失敗：', err);
        return window.GameLogic.friends || {};
    }
};

window.renderProfileFriendButton = async function(profile = null, uid = profileViewingUid, isMe = false) {
    const wrap = document.getElementById('friend-profile-action-wrap');
    const btn = document.getElementById('profile-friend-btn');
    if (!wrap || !btn || !window.GameLogic || !window.GameLogic.currentUser || !uid) return;

    const myUid = window.GameLogic.currentUser.uid;
    isMe = isMe || uid === myUid;

    if (isMe) {
        wrap.style.display = 'none';
        return;
    }

    wrap.style.display = 'block';
    btn.disabled = true;
    btn.className = 'friend-profile-btn pending';
    btn.innerText = '確認關係中……';
    btn.dataset.friendTargetUid = uid;

    try {
        const [friendSnap, outgoingSnap, incomingSnap] = await Promise.all([
            get(ref(window.GameLogic.db, `users/${myUid}/friends/${uid}`)),
            get(ref(window.GameLogic.db, `users/${uid}/friendRequests/${myUid}`)),
            get(ref(window.GameLogic.db, `users/${myUid}/friendRequests/${uid}`))
        ]);

        if (profileViewingUid !== uid) return;

        if (friendSnap.exists()) {
            btn.disabled = true;
            btn.className = 'friend-profile-btn friend';
            btn.innerText = '此蔥已是友';
            return;
        }

        if (incomingSnap.exists()) {
            btn.disabled = false;
            btn.className = 'friend-profile-btn incoming';
            btn.innerText = '對方邀你，按我答應';
            btn.dataset.friendMode = 'accept';
            return;
        }

        if (outgoingSnap.exists()) {
            btn.disabled = true;
            btn.className = 'friend-profile-btn pending';
            btn.innerText = '邀請已送出';
            return;
        }

        btn.disabled = false;
        btn.className = 'friend-profile-btn';
        btn.innerText = '新增好蔥友';
        btn.dataset.friendMode = 'send';
    } catch (err) {
        console.warn('[好蔥友] 更新身分證好友按鈕失敗：', err);
        btn.disabled = false;
        btn.className = 'friend-profile-btn';
        btn.innerText = '新增好蔥友';
        btn.dataset.friendMode = 'send';
    }
};

window.handleProfileFriendButton = async function() {
    const btn = document.getElementById('profile-friend-btn');
    const targetUid = btn && btn.dataset.friendTargetUid ? btn.dataset.friendTargetUid : profileViewingUid;
    if (!targetUid || !window.GameLogic || !window.GameLogic.currentUser) return;

    if (btn && btn.dataset.friendMode === 'accept') {
        await window.acceptFriendRequest(targetUid);
        return;
    }

    await window.sendFriendRequest(targetUid);
};

window.sendFriendRequest = async function(targetUid) {
    if (!targetUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;
    if (targetUid === myUid) return;

    const btn = document.getElementById('profile-friend-btn');
    if (btn) {
        btn.disabled = true;
        btn.className = 'friend-profile-btn pending';
        btn.innerText = '送出中……';
    }

    try {
        const [friendSnap, outgoingSnap, incomingSnap] = await Promise.all([
            get(ref(window.GameLogic.db, `users/${myUid}/friends/${targetUid}`)),
            get(ref(window.GameLogic.db, `users/${targetUid}/friendRequests/${myUid}`)),
            get(ref(window.GameLogic.db, `users/${myUid}/friendRequests/${targetUid}`))
        ]);

        if (friendSnap.exists()) {
            if (window.renderProfileFriendButton) window.renderProfileFriendButton(null, targetUid, false);
            return;
        }

        if (incomingSnap.exists()) {
            await window.acceptFriendRequest(targetUid);
            return;
        }

        if (outgoingSnap.exists()) {
            if (window.renderProfileFriendButton) window.renderProfileFriendButton(null, targetUid, false);
            window.showFriendSystemNotice('好友邀請已經送出囉');
            return;
        }

        const pairId = window.getFriendPairId(myUid, targetUid);
        const requestData = {
            fromUid: myUid,
            fromName: window.GameLogic.myProfile.name || '匿名',
            fromColor: window.GameLogic.myProfile.color || '#fff',
            createdAt: Date.now(),
            status: 'pending',
            pairId: pairId,
            roomId: window.getCurrentServerRoomId ? window.getCurrentServerRoomId() : (window.GameLogic.currentServerRoom || '')
        };

        await set(ref(window.GameLogic.db, `users/${targetUid}/friendRequests/${myUid}`), requestData);

        window.showFriendSystemNotice('已送出好蔥友邀請');
        if (window.renderProfileFriendButton) window.renderProfileFriendButton(null, targetUid, false);
    } catch (err) {
        console.warn('[好蔥友] 送出好友邀請失敗：', err);
        window.showFriendSystemNotice('好友邀請送出失敗，請稍後再試');
        if (window.renderProfileFriendButton) window.renderProfileFriendButton(null, targetUid, false);
    }
};

window.acceptCurrentFriendRequest = function() {
    if (!window.__activeFriendRequestUid) return;
    window.acceptFriendRequest(window.__activeFriendRequestUid);
};

window.rejectCurrentFriendRequest = function() {
    if (!window.__activeFriendRequestUid) return;
    window.rejectFriendRequest(window.__activeFriendRequestUid);
};

window.acceptFriendRequest = async function(fromUid) {
    if (!fromUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;
    const pairId = window.getFriendPairId(myUid, fromUid);
    const uidList = [myUid, fromUid].sort();
    const now = Date.now();

    try {
        const [requestSnap, fromProfileSnap, pairSnap] = await Promise.all([
            get(ref(window.GameLogic.db, `users/${myUid}/friendRequests/${fromUid}`)),
            get(ref(window.GameLogic.db, `users/${fromUid}`)),
            get(ref(window.GameLogic.db, `friendPairs/${pairId}`))
        ]);

        const requestData = requestSnap.val() || {};
        const fromProfile = fromProfileSnap.val() || {};
        const pairData = pairSnap.val() || {};
        const fromName = requestData.fromName || fromProfile.name || '匿名';
        const fromColor = requestData.fromColor || fromProfile.color || '#fff';
        const myName = window.GameLogic.myProfile.name || '匿名';
        const myColor = window.GameLogic.myProfile.color || '#fff';

        const updates = {};
        updates[`users/${myUid}/friends/${fromUid}`] = {
            uid: fromUid,
            name: fromName,
            color: fromColor,
            addedAt: now,
            pairId: pairId
        };
        updates[`users/${fromUid}/friends/${myUid}`] = {
            uid: myUid,
            name: myName,
            color: myColor,
            addedAt: now,
            pairId: pairId
        };
        updates[`friendPairs/${pairId}/uidA`] = uidList[0];
        updates[`friendPairs/${pairId}/uidB`] = uidList[1];
        updates[`friendPairs/${pairId}/createdAt`] = pairData.createdAt || now;
        updates[`friendPairs/${pairId}/lovePercent`] = Number(pairData.lovePercent || 0);
        updates[`users/${myUid}/friendRequests/${fromUid}`] = null;
        updates[`users/${fromUid}/friendRequests/${myUid}`] = null;

        await update(ref(window.GameLogic.db), updates);

        if (window.GameLogic.friendRequests) delete window.GameLogic.friendRequests[fromUid];
        if (!window.GameLogic.friends) window.GameLogic.friends = {};
        window.GameLogic.friends[fromUid] = updates[`users/${myUid}/friends/${fromUid}`];

        window.closeFriendRequestModal();
        window.showFriendSystemNotice(`你和 ${fromName} 已成為好蔥友！`);

        if (profileViewingUid === fromUid && window.renderProfileFriendButton) {
            window.renderProfileFriendButton(null, fromUid, false);
        }

        const phoneModal = document.getElementById('phone-modal');
        if (phoneModal && phoneModal.style.display === 'block' && window.openPhoneModal) window.openPhoneModal();
    } catch (err) {
        console.warn('[好蔥友] 接受好友邀請失敗：', err);
        window.showFriendSystemNotice('接受好友邀請失敗，請稍後再試');
    }
};

window.rejectFriendRequest = async function(fromUid) {
    if (!fromUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    try {
        await remove(ref(window.GameLogic.db, `users/${myUid}/friendRequests/${fromUid}`));
        if (window.GameLogic.friendRequests) delete window.GameLogic.friendRequests[fromUid];
        window.closeFriendRequestModal();
        window.showFriendSystemNotice('已婉拒這次好蔥友邀請');

        const phoneModal = document.getElementById('phone-modal');
        if (phoneModal && phoneModal.style.display === 'block' && window.openPhoneModal) window.openPhoneModal();
    } catch (err) {
        console.warn('[好蔥友] 拒絕好友邀請失敗：', err);
        window.showFriendSystemNotice('拒絕好友邀請失敗，請稍後再試');
    }
};

window.makePhoneFriendRequestCard = function(fromUid, requestData = {}) {
    const name = requestData.fromName || '匿名洋蔥';
    const color = window.safePhoneColor ? window.safePhoneColor(requestData.fromColor || '#fff') : '#fff';

    return `<div class="friend-request-card" data-friend-request-uid="${window.phoneEscapeHtml(fromUid)}">
        <div class="friend-request-card-title" style="color:${color};">🌱 ${window.phoneEscapeHtml(name)}</div>
        <div class="friend-request-card-sub">有蔥想加你好友</div>
        <div class="friend-request-actions">
            <button class="btn-primary" data-phone-action="accept-friend" data-uid="${window.phoneEscapeHtml(fromUid)}">好啊</button>
            <button class="btn-secondary" style="color:#333;" data-phone-action="reject-friend" data-uid="${window.phoneEscapeHtml(fromUid)}">先不要</button>
        </div>
    </div>`;
};

window.getShortFriendUid = function(uid) {
    const raw = String(uid || '');
    if (raw.length <= 10) return raw || '未知ID';
    return `${raw.slice(0, 6)}…${raw.slice(-4)}`;
};

window.getFriendMottoText = function(profile = {}, fallback = '期待發芽') {
    const raw = profile && profile.motto !== undefined ? String(profile.motto || '').trim() : '';
    if (!raw || raw === '無' || raw === '未知') return fallback;
    return raw.length > 42 ? `${raw.slice(0, 42)}…` : raw;
};

window.getFriendOnionImgHtml = function(altText = '洋蔥') {
    return `<img src="onion-sprite.png" alt="${window.phoneEscapeHtml ? window.phoneEscapeHtml(altText) : '洋蔥'}">`;
};

window.getFriendOnlineInfo = function(uid, onlinePlayers = null, options = {}) {
    const players = onlinePlayers || (window.GameLogic && window.GameLogic.onlinePlayers) || {};
    const p = players && players[uid] ? players[uid] : null;
    const mode = options.mode || 'visit';
    let fresh = p && window.isFreshOnlinePlayer ? window.isFreshOnlinePlayer(p, { mode }) : false;
    let source = p ? 'onlinePlayers' : '';
    let data = p;

    if (!fresh && window.GameLogic && window.GameLogic.doghousePlayers && window.GameLogic.doghousePlayers[uid]) {
        const dogPlayer = window.GameLogic.doghousePlayers[uid];
        if (window.isFreshOnlinePlayer && window.isFreshOnlinePlayer(dogPlayer, { mode: 'visit' })) {
            fresh = true;
            source = 'doghousePlayers';
            data = Object.assign({}, p || {}, dogPlayer || {});
        }
    }

    return {
        online: !!fresh,
        name: data && data.name ? data.name : '',
        color: data && data.color ? data.color : '',
        level: data && data.level !== undefined ? data.level : null,
        source: source
    };
};

window.makePhoneFriendCard = function(uid, friendData = {}, options = {}) {
    const onlinePlayers = options.onlinePlayers || {};
    const pairData = options.pairData || {};
    const onlineInfo = window.getFriendOnlineInfo ? window.getFriendOnlineInfo(uid, onlinePlayers) : { online: false };
    const name = onlineInfo.name || friendData.name || '匿名好友';
    const color = window.safePhoneColor ? window.safePhoneColor(onlineInfo.color || friendData.color || '#fff') : '#fff';
    const pairId = friendData.pairId || (window.getFriendPairId && window.GameLogic && window.GameLogic.currentUser ? window.getFriendPairId(window.GameLogic.currentUser.uid, uid) : '');
    const lovePercent = Number(pairData.lovePercent || friendData.lovePercent || 0);
    const loveText = Number.isFinite(lovePercent) ? lovePercent.toFixed(1) : '0.0';
    const statusClass = onlineInfo.online ? 'online' : 'offline';
    const statusText = onlineInfo.online ? '在線' : '離線';
    const visitClass = onlineInfo.online ? 'phone-visit-ready' : 'phone-visit-disabled';
    const mottoText = window.getFriendMottoText ? window.getFriendMottoText(friendData, '期待發芽') : (friendData.motto || '期待發芽');

    return `<div class="phone-friend-card" data-friend-uid="${window.phoneEscapeHtml(uid)}">
        <div class="phone-friend-title">
            <div class="phone-friend-name" style="color:${color};">🌱 ${window.phoneEscapeHtml(name)}</div>
            <div class="phone-friend-status ${statusClass}">${statusText}</div>
        </div>
        <div class="phone-friend-meta">座右銘：${window.phoneEscapeHtml(mottoText)}｜❤️ ${window.phoneEscapeHtml(loveText)}%</div>
        <div class="phone-friend-actions">
            <button class="btn-secondary" style="color:#333;" data-phone-action="profile" data-uid="${window.phoneEscapeHtml(uid)}">查看</button>
            <button class="btn-primary" data-phone-action="pm" data-uid="${window.phoneEscapeHtml(uid)}">私訊</button>
            <button class="btn-primary" data-phone-action="love-entry" data-uid="${window.phoneEscapeHtml(uid)}" data-pair-id="${window.phoneEscapeHtml(pairId)}">我們的愛</button>
            <button class="${visitClass}" data-phone-action="visit-entry" data-uid="${window.phoneEscapeHtml(uid)}" data-online="${onlineInfo.online ? '1' : '0'}">去你家</button>
        </div>
    </div>`;
};

window.openMyFriendsPhonePanel = async function() {
    if (window.__phoneFriendsRendering) return;
    window.__phoneFriendsRendering = true;

    const inventoryModal = document.getElementById('inventory-modal');
    const phoneModal = document.getElementById('phone-modal');
    const contactsEl = document.getElementById('phone-contacts');
    const subtitleEl = document.getElementById('phone-subtitle');
    const friendsBtn = document.getElementById('phone-friends-btn');

    try {
        window.clearUiBlockersAfterModal({ blur: false });

        if (inventoryModal) inventoryModal.style.display = 'none';
        if (phoneModal) phoneModal.style.display = 'block';
        if (subtitleEl) subtitleEl.innerText = '好蔥友名單｜查看、私訊、我們的愛、去你家';
        if (friendsBtn) friendsBtn.innerText = '聯絡人';
        if (friendsBtn) friendsBtn.onclick = (e) => {
            if (window.popPhoneHeaderParticles) window.popPhoneHeaderParticles(e);
            if (window.openPhoneModal) window.openPhoneModal();
        };
        if (!contactsEl) return;

        contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">讀取我的好友中...</div>';

        if (!window.GameLogic.currentUser) {
            contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">請先登入後再使用我的好友</div>';
            return;
        }

        const myUid = window.GameLogic.currentUser.uid;
        const roomName = window.getCurrentServerRoomName ? window.getCurrentServerRoomName() : '目前房間';
        const [friendsSnap, onlineSnap] = await Promise.all([
            get(ref(window.GameLogic.db, `users/${myUid}/friends`)),
            get(ref(window.GameLogic.db, window.getServerRoomPath('onlinePlayers')))
        ]);

        const friends = friendsSnap.val() || {};
        const onlinePlayers = Object.assign({}, window.GameLogic.onlinePlayers || {}, onlineSnap.val() || {});
        window.GameLogic.friends = friends;
        window.GameLogic.onlinePlayers = onlinePlayers;

        const friendUids = Object.keys(friends)
            .filter(uid => uid && uid !== myUid)
            .sort((a, b) => {
                const aOnline = window.getFriendOnlineInfo ? window.getFriendOnlineInfo(a, onlinePlayers).online : false;
                const bOnline = window.getFriendOnlineInfo ? window.getFriendOnlineInfo(b, onlinePlayers).online : false;
                if (aOnline !== bOnline) return aOnline ? -1 : 1;
                const nameA = (friends[a] && friends[a].name) || '匿名好友';
                const nameB = (friends[b] && friends[b].name) || '匿名好友';
                return nameA.localeCompare(nameB, 'zh-Hant');
            });

        const pairSnaps = await Promise.all(friendUids.map(uid => {
            const pairId = friends[uid] && friends[uid].pairId
                ? friends[uid].pairId
                : (window.getFriendPairId ? window.getFriendPairId(myUid, uid) : '');
            return pairId
                ? get(ref(window.GameLogic.db, `friendPairs/${pairId}`)).then(snap => [uid, snap.val() || {}]).catch(() => [uid, {}])
                : Promise.resolve([uid, {}]);
        }));
        const profileSnaps = await Promise.all(friendUids.map(uid => {
            return get(ref(window.GameLogic.db, `users/${uid}`))
                .then(snap => [uid, snap.val() || {}])
                .catch(() => [uid, {}]);
        }));
        const pairMap = {};
        const profileMap = {};
        pairSnaps.forEach(([uid, pairData]) => { pairMap[uid] = pairData || {}; });
        profileSnaps.forEach(([uid, profileData]) => { profileMap[uid] = profileData || {}; });

        if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
        friendUids.forEach(uid => {
            const pairId = friends[uid] && friends[uid].pairId
                ? friends[uid].pairId
                : (window.getFriendPairId ? window.getFriendPairId(myUid, uid) : '');
            if (pairId) window.GameLogic.friendPairs[pairId] = pairMap[uid] || {};
        });

        const phoneContactMeta = {};
        let html = `
            <div style="font-size:11px; color:#fff; text-shadow:1px 1px 2px #000; margin-bottom:8px;">
                目前房間：${window.phoneEscapeHtml(roomName)}
            </div>
            <div class="phone-section-title">💖 我的好友</div>
        `;

        if (friendUids.length === 0) {
            html += '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000; font-size:13px; margin:12px 0;">目前還沒有好蔥友。可以從其他玩家的洋蔥身分證送出邀請。</div>';
        } else {
            friendUids.forEach(uid => {
                const onlineInfo = window.getFriendOnlineInfo ? window.getFriendOnlineInfo(uid, onlinePlayers) : { online: false };
                const profileData = profileMap[uid] || {};
                const friendData = Object.assign({}, friends[uid] || {}, {
                    name: profileData.name || (friends[uid] && friends[uid].name) || '',
                    color: profileData.color || (friends[uid] && friends[uid].color) || '',
                    motto: profileData.motto || (friends[uid] && friends[uid].motto) || ''
                });
                const meta = {
                    uid: uid,
                    name: onlineInfo.name || friendData.name || '匿名好友',
                    color: onlineInfo.color || friendData.color || '#fff',
                    motto: window.getFriendMottoText ? window.getFriendMottoText(friendData, '期待發芽') : (friendData.motto || '期待發芽'),
                    pairId: friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, uid) : ''),
                    lovePercent: Number((pairMap[uid] && pairMap[uid].lovePercent) || friendData.lovePercent || 0),
                    online: !!onlineInfo.online
                };
                phoneContactMeta[uid] = meta;
                html += window.makePhoneFriendCard(uid, friendData, { onlinePlayers, pairData: pairMap[uid] });
            });
        }

        contactsEl.innerHTML = html;
        window.GameLogic.phoneContactMeta = Object.assign({}, window.GameLogic.phoneContactMeta || {}, phoneContactMeta);
        window.bindPhoneContactButtons(contactsEl);
    } catch (err) {
        console.warn('[我的好友] 讀取好友列表失敗：', err);
        if (contactsEl) {
            contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">我的好友讀取失敗，請稍後再試</div>';
        }
    } finally {
        window.__phoneFriendsRendering = false;
        if (window.scheduleMobileViewportRefresh) window.scheduleMobileViewportRefresh();
    }
};

window.getFriendLoveSweepBonusPercent = function(lovePercent) {
    const val = Number(lovePercent || 0);
    if (val >= 100) return 10;
    if (val >= 81) return 9;
    if (val >= 71) return 8;
    if (val >= 61) return 7;
    if (val >= 51) return 6;
    if (val >= 41) return 5;
    if (val >= 31) return 4;
    if (val >= 21) return 3;
    if (val >= 11) return 2;
    if (val >= 5) return 1;
    return 0;
};

window.getFriendLoveBonusText = function(lovePercent) {
    const bonus = window.getFriendLoveSweepBonusPercent ? window.getFriendLoveSweepBonusPercent(lovePercent) : 0;
    return bonus > 0 ? `目前效果：雙方同場時，掃地的錢多 ${bonus}%` : '目前效果：無。友好度達 5% 後，雙方同場掃地會開始增加馬德幣。';
};

window.refreshFriendPairsCache = async function(friends = null) {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return {};

    const myUid = window.GameLogic.currentUser.uid;
    const friendMap = friends || window.GameLogic.friends || {};
    const pairCache = {};

    const jobs = Object.keys(friendMap).map(uid => {
        const pairId = friendMap[uid] && friendMap[uid].pairId
            ? friendMap[uid].pairId
            : (window.getFriendPairId ? window.getFriendPairId(myUid, uid) : '');

        if (!pairId) return Promise.resolve();

        return get(ref(window.GameLogic.db, `friendPairs/${pairId}`))
            .then(snap => {
                pairCache[pairId] = snap.val() || {};
            })
            .catch(err => {
                console.warn(`[我們的愛] 讀取 ${pairId} 失敗：`, err);
            });
    });

    await Promise.all(jobs);
    window.GameLogic.friendPairs = Object.assign({}, window.GameLogic.friendPairs || {}, pairCache);
    return window.GameLogic.friendPairs;
};

window.getFriendLovePairData = async function(friendUid) {
    if (!friendUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return null;

    const myUid = window.GameLogic.currentUser.uid;
    const friendData = (window.GameLogic.friends && window.GameLogic.friends[friendUid]) || {};
    const pairId = friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, friendUid) : '');

    if (!pairId) return null;

    try {
        const snap = await get(ref(window.GameLogic.db, `friendPairs/${pairId}`));
        const pairData = snap.val() || {};
        if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
        window.GameLogic.friendPairs[pairId] = pairData;
        return { pairId, pairData };
    } catch (err) {
        console.warn('[我們的愛] 讀取共同友好度失敗：', err);
        return { pairId, pairData: (window.GameLogic.friendPairs && window.GameLogic.friendPairs[pairId]) || {} };
    }
};

window.closeFriendLoveModal = function() {
    const modal = document.getElementById('friend-love-modal');
    if (modal) modal.style.display = 'none';
};

window.renderFriendLoveModal = function(friendUid, data = {}) {
    const modal = document.getElementById('friend-love-modal');
    const content = document.getElementById('friend-love-content');
    if (!modal || !content || !window.GameLogic || !window.GameLogic.currentUser) return;

    const myUid = window.GameLogic.currentUser.uid;
    const myProfile = window.GameLogic.myProfile || {};
    const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[friendUid]) || {};
    const friendData = (window.GameLogic.friends && window.GameLogic.friends[friendUid]) || {};
    const friendProfile = data.friendProfile || {};
    const pairData = data.pairData || {};
    const lovePercent = Number(pairData.lovePercent || meta.lovePercent || friendData.lovePercent || 0);
    const loveText = Number.isFinite(lovePercent) ? lovePercent.toFixed(1) : '0.0';
    const myName = myProfile.name || '我';
    const friendName = friendProfile.name || meta.name || friendData.name || '好友';
    const myColor = window.safePhoneColor ? window.safePhoneColor(myProfile.color || '#ff8bd4') : '#ff8bd4';
    const friendColor = window.safePhoneColor ? window.safePhoneColor(friendProfile.color || meta.color || friendData.color || '#7fffea') : '#7fffea';
    const bonusText = window.getFriendLoveBonusText ? window.getFriendLoveBonusText(lovePercent) : '目前效果：無';
    const myShortId = window.getShortFriendUid ? window.getShortFriendUid(myUid) : myUid;
    const friendShortId = window.getShortFriendUid ? window.getShortFriendUid(friendUid) : friendUid;

    content.innerHTML = `
        <h3 class="friend-love-title">💖 我們的愛</h3>
        <div class="friend-love-people-row">
            <div class="friend-love-person">
                <div class="friend-love-avatar" style="--friend-love-color:${myColor};">${window.getFriendOnionImgHtml ? window.getFriendOnionImgHtml(myName) : '<img src="onion-sprite.png" alt="洋蔥">'}</div>
                <div class="friend-love-name">${window.phoneEscapeHtml(myName)}</div>
                <div class="friend-love-id">ID：${window.phoneEscapeHtml(myShortId)}</div>
            </div>
            <div class="friend-love-heart-wrap" aria-hidden="true">
                <div class="friend-love-heart">❤️</div>
            </div>
            <div class="friend-love-person">
                <div class="friend-love-avatar" style="--friend-love-color:${friendColor};">${window.getFriendOnionImgHtml ? window.getFriendOnionImgHtml(friendName) : '<img src="onion-sprite.png" alt="洋蔥">'}</div>
                <div class="friend-love-name">${window.phoneEscapeHtml(friendName)}</div>
                <div class="friend-love-id">ID：${window.phoneEscapeHtml(friendShortId)}</div>
            </div>
        </div>
        <div class="friend-love-percent">❤️=${window.phoneEscapeHtml(loveText)}%</div>
        <div class="friend-love-bonus">${window.phoneEscapeHtml(bonusText)}</div>
        <div class="friend-love-actions single">
            <button class="btn-secondary" type="button" onclick="window.closeFriendLoveModal && window.closeFriendLoveModal()">關閉</button>
        </div>
    `;

    modal.style.display = 'block';
};

window.openFriendLoveEntry = async function(uid) {
    if (!uid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const modal = document.getElementById('friend-love-modal');
    const content = document.getElementById('friend-love-content');
    if (modal && content) {
        content.innerHTML = `
            <h3 class="friend-love-title">💖 我們的愛</h3>
            <div style="font-size:13px; color:#fff7ff; text-shadow:0 1px 2px rgba(0,0,0,0.65);">讀取好蔥友情中……</div>
        `;
        modal.style.display = 'block';
    }

    try {
        const [pairResult, friendProfileSnap] = await Promise.all([
            window.getFriendLovePairData ? window.getFriendLovePairData(uid) : Promise.resolve(null),
            get(ref(window.GameLogic.db, `users/${uid}`)).catch(() => null)
        ]);

        const friendProfile = friendProfileSnap && friendProfileSnap.exists ? (friendProfileSnap.val() || {}) : {};
        const pairData = pairResult && pairResult.pairData ? pairResult.pairData : {};
        window.renderFriendLoveModal(uid, { friendProfile, pairData });
    } catch (err) {
        console.warn('[我們的愛] 開啟介面失敗：', err);
        window.showFriendSystemNotice('我們的愛讀取失敗，請稍後再試');
        if (modal) modal.style.display = 'none';
    }
};

window.isFriendActiveInSameScene = function(friendUid) {
    if (!friendUid || !window.GameLogic || !window.GameLogic.currentUser) return false;
    if (!window.GameLogic.friends || !window.GameLogic.friends[friendUid]) return false;

    const onlinePlayers = window.GameLogic.onlinePlayers || {};
    const player = onlinePlayers[friendUid];
    if (!player) return false;

    const fresh = window.isFreshPhoneOnlinePlayer ? window.isFreshPhoneOnlinePlayer(player) : true;
    if (!fresh) return false;

    const currentScene = window.GameLogic.currentScene || 'cafe';
    const playerScene = player.scene || '';

    if (playerScene) return playerScene === currentScene;

    if (currentScene === 'cafe') return !!(window.GameLogic.cafePlayers && window.GameLogic.cafePlayers[friendUid]);
    if (currentScene === 'shrine') return !!(window.GameLogic.shrinePlayers && window.GameLogic.shrinePlayers[friendUid]);
    if (currentScene === 'playroom') return !!(window.GameLogic.playroomPlayers && window.GameLogic.playroomPlayers[friendUid]);
    if (currentScene === 'partyroom' && window.PartyLogic && window.PartyLogic.players) return !!window.PartyLogic.players[friendUid];

    return false;
};

window.getActiveFriendLoveSweepBonus = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser) return null;

    const friends = window.GameLogic.friends || {};
    const pairCache = window.GameLogic.friendPairs || {};
    const myUid = window.GameLogic.currentUser.uid;
    let best = null;

    Object.keys(friends).forEach(friendUid => {
        if (!window.isFriendActiveInSameScene || !window.isFriendActiveInSameScene(friendUid)) return;

        const friendData = friends[friendUid] || {};
        const pairId = friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, friendUid) : '');
        const pairData = pairCache[pairId] || {};
        const lovePercent = Number(pairData.lovePercent || friendData.lovePercent || 0);
        const bonusPercent = window.getFriendLoveSweepBonusPercent ? window.getFriendLoveSweepBonusPercent(lovePercent) : 0;
        if (bonusPercent <= 0) return;

        const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[friendUid]) || {};
        const onlineInfo = window.getFriendOnlineInfo ? window.getFriendOnlineInfo(friendUid) : {};
        const name = onlineInfo.name || meta.name || friendData.name || '好友';

        if (!best || bonusPercent > best.bonusPercent || lovePercent > best.lovePercent) {
            best = {
                friendUid,
                pairId,
                name,
                lovePercent,
                bonusPercent,
                bonusRate: bonusPercent / 100
            };
        }
    });

    window.GameLogic.activeFriendLoveBonus = best;
    return best;
};

window.showFriendLoveToast = function(message) {
    const safeMessage = message || '❤️ 好蔥友情升溫 +0.1%';
    const scene = window.GameLogic && window.GameLogic.phaserGame
        ? window.GameLogic.phaserGame.scene.getScene('MainScene')
        : null;

    if (scene && scene.showPrinceCatFriendshipHint) {
        scene.showPrinceCatFriendshipHint(null, safeMessage);
        return;
    }

    const oldToast = document.querySelector('.friend-love-toast');
    if (oldToast) oldToast.remove();

    const toast = document.createElement('div');
    toast.className = 'friend-love-toast';
    toast.innerText = safeMessage;
    document.body.appendChild(toast);

    setTimeout(() => {
        if (toast && toast.remove) toast.remove();
    }, 1700);
};

window.addFriendLovePercent = async function(friendUid, amount = 0.1, options = {}) {
    if (!friendUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return null;

    const myUid = window.GameLogic.currentUser.uid;
    const friendData = (window.GameLogic.friends && window.GameLogic.friends[friendUid]) || {};
    const pairId = friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, friendUid) : '');
    if (!pairId) return null;

    try {
        const pairSnap = await get(ref(window.GameLogic.db, `friendPairs/${pairId}`));
        const pairData = pairSnap.val() || {};
        const oldLove = Number(pairData.lovePercent || 0);
        const addVal = Number(amount || 0);
        const nextLove = Math.max(0, oldLove + addVal);
        const uidList = [myUid, friendUid].sort();

        const updates = {};
        updates[`friendPairs/${pairId}/uidA`] = pairData.uidA || uidList[0];
        updates[`friendPairs/${pairId}/uidB`] = pairData.uidB || uidList[1];
        updates[`friendPairs/${pairId}/createdAt`] = pairData.createdAt || Date.now();
        updates[`friendPairs/${pairId}/lovePercent`] = Number(nextLove.toFixed(1));
        updates[`friendPairs/${pairId}/updatedAt`] = Date.now();

        await update(ref(window.GameLogic.db), updates);

        if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
        window.GameLogic.friendPairs[pairId] = Object.assign({}, pairData, {
            uidA: updates[`friendPairs/${pairId}/uidA`],
            uidB: updates[`friendPairs/${pairId}/uidB`],
            lovePercent: updates[`friendPairs/${pairId}/lovePercent`],
            updatedAt: updates[`friendPairs/${pairId}/updatedAt`]
        });

        const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[friendUid]) || {};
        const friendName = options.friendName || meta.name || friendData.name || '好友';
        if (options.silent !== true && window.showFriendLoveToast) {
            window.showFriendLoveToast(`和 ${friendName} 的友好度 +${addVal.toFixed(1)}%`);
        }

        return window.GameLogic.friendPairs[pairId];
    } catch (err) {
        console.warn('[我們的愛] 增加友好度失敗：', err);
        return null;
    }
};

window.getFriendVisitLoveDateKey = function(date = new Date()) {
    if (window.getMeowlimeTodayDateString) return window.getMeowlimeTodayDateString(date);

    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
};

window.getFriendVisitLoveDirectionKey = function(visitorUid, hostUid) {
    return `${visitorUid || ''}_to_${hostUid || ''}`.replace(/[.#$[\]/]/g, '_');
};

window.tryGrantFriendVisitLoveReward = async function(hostUid, hostName = '') {
    if (!hostUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return { ok: false, reason: 'missing-context' };

    const visitorUid = window.GameLogic.currentUser.uid;
    if (!visitorUid || hostUid === visitorUid) return { ok: false, reason: 'not-visitor' };

    const safeHostName = hostName || (window.GameLogic.doghouseHostProfile && window.GameLogic.doghouseHostProfile.name) || '好友';
    const visitorName = window.GameLogic.myProfile && window.GameLogic.myProfile.name ? window.GameLogic.myProfile.name : '好友';
    const dateKey = window.getFriendVisitLoveDateKey ? window.getFriendVisitLoveDateKey() : '';
    const directionKey = window.getFriendVisitLoveDirectionKey ? window.getFriendVisitLoveDirectionKey(visitorUid, hostUid) : `${visitorUid}_to_${hostUid}`;
    const localLockKey = `${dateKey}_${directionKey}`;

    if (!dateKey || !directionKey) return { ok: false, reason: 'missing-date-or-direction' };

    if (!window.__friendVisitLoveRewardLocalLocks) window.__friendVisitLoveRewardLocalLocks = {};
    if (window.__friendVisitLoveRewardLocalLocks[localLockKey]) return { ok: false, reason: 'local-locked' };
    window.__friendVisitLoveRewardLocalLocks[localLockKey] = true;

    try {
        const friendData = (window.GameLogic.friends && window.GameLogic.friends[hostUid]) || {};
        const pairId = friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(visitorUid, hostUid) : '');
        if (!pairId) return { ok: false, reason: 'missing-pair' };

        const uidList = [visitorUid, hostUid].sort();
        const addVal = 0.1;
        const now = Date.now();
        let alreadyGranted = false;
        let nextLove = 0;

        const txResult = await runTransaction(ref(window.GameLogic.db, `friendPairs/${pairId}`), (pairData) => {
            const currentPair = pairData || {};
            const dailyVisitLove = currentPair.dailyVisitLove || {};
            const todayMap = dailyVisitLove[dateKey] || {};

            if (todayMap[directionKey]) {
                alreadyGranted = true;
                nextLove = Number(currentPair.lovePercent || 0);
                return currentPair;
            }

            const oldLove = Number(currentPair.lovePercent || friendData.lovePercent || 0);
            nextLove = Number(Math.max(0, oldLove + addVal).toFixed(1));

            return Object.assign({}, currentPair, {
                uidA: currentPair.uidA || uidList[0],
                uidB: currentPair.uidB || uidList[1],
                createdAt: currentPair.createdAt || now,
                lovePercent: nextLove,
                updatedAt: now,
                dailyVisitLove: Object.assign({}, dailyVisitLove, {
                    [dateKey]: Object.assign({}, todayMap, {
                        [directionKey]: {
                            visitorUid: visitorUid,
                            hostUid: hostUid,
                            visitorName: visitorName,
                            hostName: safeHostName,
                            amount: addVal,
                            date: dateKey,
                            createdAt: now
                        }
                    })
                })
            });
        });

        const nextPairData = txResult && txResult.snapshot ? (txResult.snapshot.val() || {}) : {};
        if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
        window.GameLogic.friendPairs[pairId] = nextPairData;

        if (alreadyGranted) return { ok: true, alreadyGranted: true, pairId, lovePercent: nextLove, dateKey, directionKey };

        set(ref(window.GameLogic.db, `users/${hostUid}/friendVisitLoveNotices/${dateKey}_${directionKey}`), {
            type: 'friendVisitLove',
            pairId: pairId,
            visitorUid: visitorUid,
            hostUid: hostUid,
            visitorName: visitorName,
            hostName: safeHostName,
            amount: addVal,
            lovePercent: Number(nextPairData.lovePercent || nextLove || 0),
            date: dateKey,
            createdAt: now
        }).catch(err => console.warn('[好友拜訪] 發送屋主友好度提示失敗：', err));

        if (window.showFriendLoveToast) window.showFriendLoveToast(`去 ${safeHostName} 家拜訪成功，友好度 +0.1%`);
        return { ok: true, alreadyGranted: false, pairId, lovePercent: Number(nextPairData.lovePercent || nextLove || 0), dateKey, directionKey };
    } catch (err) {
        delete window.__friendVisitLoveRewardLocalLocks[localLockKey];
        console.warn('[好友拜訪] 拜訪友好度加成失敗：', err);
        return { ok: false, reason: 'grant-failed', error: err };
    }
};

window.tryGrantFriendDailyLoveAction = async function(friendUid, actionKey, actionLabel = '共同活動', options = {}) {
    if (!friendUid || !actionKey || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return { ok: false, reason: 'missing-context' };

    const myUid = window.GameLogic.currentUser.uid;
    if (!myUid || friendUid === myUid) return { ok: false, reason: 'invalid-friend' };

    let friendData = (window.GameLogic.friends && window.GameLogic.friends[friendUid]) || null;

    try {
        if (!friendData || !friendData.pairId) {
            const friendSnap = await get(ref(window.GameLogic.db, `users/${myUid}/friends/${friendUid}`));
            if (!friendSnap.exists()) return { ok: false, reason: 'not-friends' };
            friendData = friendSnap.val() || {};
            if (!window.GameLogic.friends) window.GameLogic.friends = {};
            window.GameLogic.friends[friendUid] = friendData;
        }

        const pairId = friendData.pairId || (window.getFriendPairId ? window.getFriendPairId(myUid, friendUid) : '');
        if (!pairId) return { ok: false, reason: 'missing-pair' };

        const dateKey = window.getFriendVisitLoveDateKey ? window.getFriendVisitLoveDateKey() : '';
        const safeActionKey = String(actionKey).replace(/[.#$[\]/]/g, '_');
        if (!dateKey || !safeActionKey) return { ok: false, reason: 'missing-date-or-action' };

        const localLockKey = `${dateKey}_${pairId}_${safeActionKey}`;
        if (!window.__friendDailyLoveActionLocalLocks) window.__friendDailyLoveActionLocalLocks = {};
        if (window.__friendDailyLoveActionLocalLocks[localLockKey]) return { ok: false, reason: 'local-locked' };
        window.__friendDailyLoveActionLocalLocks[localLockKey] = true;

        const addVal = Number(options.amount || 0.1);
        const now = Date.now();
        const myName = window.GameLogic.myProfile && window.GameLogic.myProfile.name ? window.GameLogic.myProfile.name : '好友';
        const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[friendUid]) || {};
        const friendName = options.friendName || meta.name || friendData.name || '好友';
        const uidList = [myUid, friendUid].sort();
        let alreadyGranted = false;
        let nextLove = 0;

        const txResult = await runTransaction(ref(window.GameLogic.db, `friendPairs/${pairId}`), (pairData) => {
            const currentPair = pairData || {};
            const dailyLoveActions = currentPair.dailyLoveActions || {};
            const todayMap = dailyLoveActions[dateKey] || {};

            if (todayMap[safeActionKey]) {
                alreadyGranted = true;
                nextLove = Number(currentPair.lovePercent || friendData.lovePercent || 0);
                return currentPair;
            }

            const oldLove = Number(currentPair.lovePercent || friendData.lovePercent || 0);
            nextLove = Number(Math.max(0, oldLove + addVal).toFixed(1));

            return Object.assign({}, currentPair, {
                uidA: currentPair.uidA || uidList[0],
                uidB: currentPair.uidB || uidList[1],
                createdAt: currentPair.createdAt || now,
                lovePercent: nextLove,
                updatedAt: now,
                dailyLoveActions: Object.assign({}, dailyLoveActions, {
                    [dateKey]: Object.assign({}, todayMap, {
                        [safeActionKey]: {
                            actorUid: myUid,
                            friendUid: friendUid,
                            actorName: myName,
                            friendName: friendName,
                            actionKey: safeActionKey,
                            actionLabel: actionLabel || '共同活動',
                            amount: addVal,
                            date: dateKey,
                            createdAt: now
                        }
                    })
                })
            });
        });

        const nextPairData = txResult && txResult.snapshot ? (txResult.snapshot.val() || {}) : {};
        if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
        window.GameLogic.friendPairs[pairId] = nextPairData;

        if (alreadyGranted) return { ok: true, alreadyGranted: true, pairId, lovePercent: Number(nextPairData.lovePercent || nextLove || 0), dateKey, actionKey: safeActionKey };

        const lovePercent = Number(nextPairData.lovePercent || nextLove || 0);
        const toastMessage = options.toastMessage || `和 ${friendName} 完成${actionLabel || '共同活動'}，友好度 +${addVal.toFixed(1)}%`;
        const noticeMessage = options.noticeMessage || `${myName}和你完成${actionLabel || '共同活動'}，友好度 +${addVal.toFixed(1)}%`;
        const noticeKey = `${dateKey}_${pairId}_${safeActionKey}`.replace(/[.#$[\]/]/g, '_');

        set(ref(window.GameLogic.db, `users/${friendUid}/friendVisitLoveNotices/${noticeKey}`), {
            type: 'friendLoveAction',
            pairId: pairId,
            actorUid: myUid,
            friendUid: friendUid,
            actorName: myName,
            friendName: friendName,
            actionKey: safeActionKey,
            actionLabel: actionLabel || '共同活動',
            amount: addVal,
            lovePercent: lovePercent,
            message: noticeMessage,
            date: dateKey,
            createdAt: now
        }).catch(err => console.warn('[共同友好度] 發送好友提示失敗：', err));

        if (window.showFriendLoveToast) window.showFriendLoveToast(toastMessage);
        return { ok: true, alreadyGranted: false, pairId, lovePercent, dateKey, actionKey: safeActionKey };
    } catch (err) {
        console.warn('[共同友好度] 活動友好度加成失敗：', err);
        return { ok: false, reason: 'grant-failed', error: err };
    }
};

window.startFriendVisitLoveNoticesListener = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    if (friendVisitLoveNoticesUnsubscribe) {
        friendVisitLoveNoticesUnsubscribe();
        friendVisitLoveNoticesUnsubscribe = null;
    }

    friendVisitLoveNoticesUnsubscribe = onValue(ref(window.GameLogic.db, `users/${myUid}/friendVisitLoveNotices`), snap => {
        const notices = snap.val() || {};
        if (!window.__shownFriendVisitLoveNoticeKeys) window.__shownFriendVisitLoveNoticeKeys = {};

        Object.keys(notices).forEach(noticeKey => {
            const item = notices[noticeKey] || {};
            if (!item || !item.createdAt) return;

            if (Date.now() - Number(item.createdAt || 0) > 120000) {
                remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitLoveNotices/${noticeKey}`));
                return;
            }

            if (window.__shownFriendVisitLoveNoticeKeys[noticeKey]) return;
            window.__shownFriendVisitLoveNoticeKeys[noticeKey] = true;

            if (item.pairId) {
                if (!window.GameLogic.friendPairs) window.GameLogic.friendPairs = {};
                window.GameLogic.friendPairs[item.pairId] = Object.assign({}, window.GameLogic.friendPairs[item.pairId] || {}, {
                    lovePercent: Number(item.lovePercent || 0),
                    updatedAt: Number(item.createdAt || Date.now())
                });
            }

            if (item.type === 'friendLoveAction') {
                if (window.showFriendLoveToast) window.showFriendLoveToast(item.message || '好友共同活動完成，友好度 +0.1%');
            } else if (item.type === 'friendVisitLove') {
                const visitorName = item.visitorName || '好友';
                if (window.showFriendLoveToast) window.showFriendLoveToast(`${visitorName}來你家拜訪成功，友好度 +0.1%`);
            } else {
                return;
            }

            remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitLoveNotices/${noticeKey}`));
        });
    });
};

window.getCurrentDoghouseHostUid = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser) return '';
    return window.GameLogic.doghouseHostUid || window.GameLogic.currentUser.uid;
};

window.isVisitingFriendDoghouse = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser) return false;
    const hostUid = window.getCurrentDoghouseHostUid ? window.getCurrentDoghouseHostUid() : window.GameLogic.currentUser.uid;
    return !!(hostUid && hostUid !== window.GameLogic.currentUser.uid);
};

window.applyDoghouseHost = function(hostUid = null, hostName = '') {
    if (!window.GameLogic || !window.GameLogic.currentUser) return '';

    const myUid = window.GameLogic.currentUser.uid;
    const safeHostUid = hostUid || myUid;
    const isVisitor = safeHostUid !== myUid;

    window.GameLogic.doghouseHostUid = safeHostUid;
    window.GameLogic.isDoghouseVisitor = isVisitor;
    window.GameLogic.doghouseHostProfile = {
        uid: safeHostUid,
        name: hostName || (isVisitor ? '好友' : (window.GameLogic.myProfile && window.GameLogic.myProfile.name ? window.GameLogic.myProfile.name : '我'))
    };

    if (!isVisitor) {
        window.GameLogic.doghouseVisitHostName = '';
    } else if (hostName) {
        window.GameLogic.doghouseVisitHostName = hostName;
    }

    return safeHostUid;
};

window.getDoghouseFurniturePath = function(hostUid = null) {
    const safeHostUid = hostUid || (window.getCurrentDoghouseHostUid ? window.getCurrentDoghouseHostUid() : (window.GameLogic && window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : ''));
    return safeHostUid ? `users/${safeHostUid}/doghouseFurniture` : '';
};

window.getDoghousePlayersPath = function(hostUid = null) {
    const safeHostUid = hostUid || (window.getCurrentDoghouseHostUid ? window.getCurrentDoghouseHostUid() : (window.GameLogic && window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : ''));
    return safeHostUid ? `users/${safeHostUid}/doghousePlayers` : '';
};

window.enterOwnDoghouse = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser) return;
    const myUid = window.GameLogic.currentUser.uid;
    const myName = window.GameLogic.myProfile && window.GameLogic.myProfile.name ? window.GameLogic.myProfile.name : '我';
    if (window.applyDoghouseHost) window.applyDoghouseHost(myUid, myName);
    window.switchScene('doghouse', { doghouseHostUid: myUid, doghouseHostName: myName });
};

window.enterFriendDoghouse = async function(hostUid, hostName = '', options = {}) {
    if (!hostUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return false;

    const myUid = window.GameLogic.currentUser.uid;
    const safeHostName = hostName || (hostUid === myUid ? (window.GameLogic.myProfile.name || '我') : '好友');

    try {
        if (hostUid !== myUid) {
            const friendSnap = await get(ref(window.GameLogic.db, `users/${myUid}/friends/${hostUid}`));
            if (!friendSnap.exists()) {
                window.showFriendSystemNotice('要先成為好蔥友才能拜訪喔');
                return false;
            }
        }

        if (window.applyDoghouseHost) window.applyDoghouseHost(hostUid, safeHostName);

        window.GameLogic.pendingDoghouseHostUid = hostUid;
        window.GameLogic.pendingDoghouseHostName = safeHostName;

        window.switchScene('doghouse', {
            doghouseHostUid: hostUid,
            doghouseHostName: safeHostName,
            visitSource: options.source || 'friendVisit'
        });

        if (window.scheduleDoghousePresenceRefresh) {
            window.scheduleDoghousePresenceRefresh(280);
            window.scheduleDoghousePresenceRefresh(900);
        }

        await new Promise(resolve => setTimeout(resolve, 520));

        const ackOk = window.waitForDoghousePresenceAck
            ? await window.waitForDoghousePresenceAck(hostUid, {
                attempts: options.ackAttempts || 5,
                intervalMs: options.ackIntervalMs || 380,
                ensureWrite: true,
                reason: options.source || 'enterFriendDoghouse'
            })
            : false;

        if (!ackOk) {
            console.warn('[好友拜訪] 尚未確認進入目標狗窩：', hostUid);
            return false;
        }

        return true;
    } catch (err) {
        console.warn('[好友拜訪] 進入好友狗窩失敗：', err);
        window.showFriendSystemNotice('前往好友家失敗，請稍後再試');
        return false;
    }
};

window.normalizeFriendVisitRequests = function(rawRequests = {}) {
    const result = {};
    const myUid = window.GameLogic && window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : '';

    if (!rawRequests || typeof rawRequests !== 'object') return result;

    Object.keys(rawRequests).forEach(fromUid => {
        const item = rawRequests[fromUid] || {};
        if (!fromUid || fromUid === myUid) return;
        if (item.status && item.status !== 'pending') return;

        const createdAt = Number(item.createdAt || item.updatedAt || 0);
        const updatedAt = Number(item.updatedAt || item.createdAt || createdAt || 0);
        const requestId = item.requestId || (createdAt ? `${fromUid}_${createdAt}` : `legacy_${fromUid}`);

        result[fromUid] = {
            fromUid: item.fromUid || fromUid,
            fromName: item.fromName || '匿名洋蔥',
            fromColor: item.fromColor || '#fff',
            hostUid: item.hostUid || myUid,
            createdAt: createdAt,
            updatedAt: updatedAt,
            requestId: requestId
        };
    });

    return result;
};

window.closeFriendVisitRequestModal = function() {
    const modal = document.getElementById('friend-visit-request-modal');
    if (modal) modal.style.display = 'none';
};

window.showIncomingFriendVisitRequest = function(fromUid, requestData = {}) {
    const modal = document.getElementById('friend-visit-request-modal');
    const nameEl = document.getElementById('friend-visit-request-name');
    if (!modal) return;

    window.__activeFriendVisitRequestUid = fromUid;
    if (nameEl) nameEl.innerText = requestData.fromName || '某顆蔥';
    modal.style.display = 'block';
};

window.startFriendVisitRequestsListener = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    if (friendVisitRequestsUnsubscribe) {
        friendVisitRequestsUnsubscribe();
        friendVisitRequestsUnsubscribe = null;
    }

    window.__shownFriendVisitRequestKeys = {};

    friendVisitRequestsUnsubscribe = onValue(ref(window.GameLogic.db, `users/${myUid}/friendVisitRequests`), snap => {
        const requests = window.normalizeFriendVisitRequests ? window.normalizeFriendVisitRequests(snap.val() || {}) : {};
        window.GameLogic.friendVisitRequests = requests;

        const requestUids = Object.keys(requests).sort((a, b) => {
            const bTime = Number(requests[b].updatedAt || requests[b].createdAt || 0);
            const aTime = Number(requests[a].updatedAt || requests[a].createdAt || 0);
            return bTime - aTime;
        });

        if (!window.__shownFriendVisitRequestKeys) window.__shownFriendVisitRequestKeys = {};

        const activeRequestKeys = {};
        requestUids.forEach(uid => {
            const item = requests[uid] || {};
            const key = item.requestId || `${uid}_${item.updatedAt || item.createdAt || 0}`;
            if (key) activeRequestKeys[key] = true;
        });

        Object.keys(window.__shownFriendVisitRequestKeys).forEach(key => {
            if (!activeRequestKeys[key]) delete window.__shownFriendVisitRequestKeys[key];
        });

        const freshUid = requestUids.find(uid => {
            const item = requests[uid] || {};
            const key = item.requestId || `${uid}_${item.updatedAt || item.createdAt || 0}`;
            return key && !window.__shownFriendVisitRequestKeys[key];
        });

        if (freshUid) {
            const freshItem = requests[freshUid] || {};
            const freshKey = freshItem.requestId || `${freshUid}_${freshItem.updatedAt || freshItem.createdAt || 0}`;
            window.__shownFriendVisitRequestKeys[freshKey] = true;
            window.showFriendSystemNotice('有蔥想來你家拜訪');
            window.showIncomingFriendVisitRequest(freshUid, freshItem);
        }
    });
};

window.startFriendVisitRepliesListener = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    if (friendVisitRepliesUnsubscribe) {
        friendVisitRepliesUnsubscribe();
        friendVisitRepliesUnsubscribe = null;
    }

    window.__processingFriendVisitReplyKeys = {};

    friendVisitRepliesUnsubscribe = onValue(ref(window.GameLogic.db, `users/${myUid}/friendVisitReplies`), snap => {
        const replies = snap.val() || {};

        Object.keys(replies).forEach(async hostUid => {
            const item = replies[hostUid] || {};
            if (!item || !item.status || !item.createdAt) return;

            const createdAt = Number(item.createdAt || item.updatedAt || 0);
            const replyKey = item.replyId || `${hostUid}_${createdAt || item.updatedAt || item.status || 'reply'}`;

            if (window.__processingFriendVisitReplyKeys && window.__processingFriendVisitReplyKeys[replyKey]) return;

            const serverNow = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();

            if (createdAt && serverNow - createdAt > 120000) {
                remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitReplies/${hostUid}`));
                return;
            }

            if (!window.__processingFriendVisitReplyKeys) window.__processingFriendVisitReplyKeys = {};
            window.__processingFriendVisitReplyKeys[replyKey] = true;

            const hostName = item.hostName || '對方';

            try {
                if (item.status === 'accepted') {
                    window.showFriendSystemNotice(`${hostName}答應你去他家囉！`);

                    let enterOk = false;
                    if (window.enterFriendDoghouse) {
                        enterOk = await window.enterFriendDoghouse(hostUid, hostName, { source: 'visitReply', replyKey });
                    }

                    if (!enterOk && window.enterFriendDoghouse) {
                        await new Promise(resolve => setTimeout(resolve, 900));
                        enterOk = await window.enterFriendDoghouse(hostUid, hostName, { source: 'visitReplyRetry', replyKey });
                    }

                    if (enterOk) {
                        await remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitReplies/${hostUid}`));
                    } else {
                        console.warn('[好友拜訪] accepted reply 已保留，等待下次同步重試：', replyKey);
                        window.showFriendSystemNotice('好友答應了，但前往他家暫時失敗，請再試一次');
                    }
                } else if (item.status === 'rejected') {
                    window.showFriendSystemNotice(`${hostName}說下次再來。`);
                    await remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitReplies/${hostUid}`));
                }
            } catch (err) {
                console.warn('[好友拜訪] 處理拜訪回覆失敗：', err);
            } finally {
                setTimeout(() => {
                    if (window.__processingFriendVisitReplyKeys) delete window.__processingFriendVisitReplyKeys[replyKey];
                }, 1200);
            }
        });
    });
};

window.startFriendVisitSessionsListener = function() {
    if (!window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;

    if (friendVisitSessionsUnsubscribe) {
        friendVisitSessionsUnsubscribe();
        friendVisitSessionsUnsubscribe = null;
    }

    window.__processingFriendVisitSessionKeys = {};

    friendVisitSessionsUnsubscribe = onValue(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions`), snap => {
        const sessions = snap.val() || {};

        Object.keys(sessions).forEach(async hostUid => {
            const item = sessions[hostUid] || {};
            if (!item || item.status !== 'go' || !item.hostUid) return;

            const createdAt = Number(item.createdAt || item.updatedAt || 0);
            const retryCount = Number(item.retryCount || 0);
            const sessionKey = item.sessionId || `${hostUid}_${createdAt || item.updatedAt || 'session'}`;
            if (!sessionKey) return;

            if (window.__processingFriendVisitSessionKeys && window.__processingFriendVisitSessionKeys[sessionKey]) return;

            const serverNow = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();

            if (createdAt && serverNow - createdAt > 120000) {
                remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions/${hostUid}`));
                return;
            }

            if (retryCount >= 4) {
                update(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions/${hostUid}`), {
                    status: 'failed',
                    updatedAt: serverNow,
                    lastError: 'retry-limit'
                }).catch(err => console.warn('[好友拜訪] 標記 visitSession 失敗狀態失敗：', err));
                return;
            }

            if (!window.__processingFriendVisitSessionKeys) window.__processingFriendVisitSessionKeys = {};
            window.__processingFriendVisitSessionKeys[sessionKey] = true;

            try {
                const targetHostUid = item.hostUid || hostUid;
                const targetHostName = item.hostName || '好友';
                const alreadyAcked = window.waitForDoghousePresenceAck
                    ? await window.waitForDoghousePresenceAck(targetHostUid, {
                        attempts: 1,
                        intervalMs: 200,
                        ensureWrite: false,
                        reason: 'visitSessionPrecheck'
                    })
                    : false;

                let enterOk = alreadyAcked;
                if (!enterOk && window.enterFriendDoghouse) {
                    window.showFriendSystemNotice(`${targetHostName}答應你去他家囉！`);
                    enterOk = await window.enterFriendDoghouse(targetHostUid, targetHostName, {
                        source: 'visitSession',
                        sessionId: sessionKey,
                        ackAttempts: 6,
                        ackIntervalMs: 360
                    });
                }

                if (!enterOk && window.enterFriendDoghouse) {
                    await new Promise(resolve => setTimeout(resolve, 900));
                    enterOk = await window.enterFriendDoghouse(targetHostUid, targetHostName, {
                        source: 'visitSessionRetry',
                        sessionId: sessionKey,
                        ackAttempts: 5,
                        ackIntervalMs: 420
                    });
                }

                const finalAck = enterOk && window.waitForDoghousePresenceAck
                    ? await window.waitForDoghousePresenceAck(targetHostUid, {
                        attempts: 2,
                        intervalMs: 280,
                        ensureWrite: true,
                        reason: 'visitSessionFinalAck'
                    })
                    : enterOk;

                if (finalAck) {
                    const arrivedNow = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();
                    await update(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions/${hostUid}`), {
                        status: 'arrived',
                        arrivedAt: arrivedNow,
                        updatedAt: arrivedNow
                    });
                    await remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions/${hostUid}`));
                    await remove(ref(window.GameLogic.db, `users/${myUid}/friendVisitReplies/${hostUid}`)).catch(() => {});
                } else {
                    await update(ref(window.GameLogic.db, `users/${myUid}/friendVisitSessions/${hostUid}`), {
                        status: 'go',
                        retryCount: retryCount + 1,
                        updatedAt: window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now(),
                        lastError: 'ack-missing'
                    });
                    console.warn('[好友拜訪] visitSession 尚未取得 doghousePlayers ack：', sessionKey);
                }
            } catch (err) {
                console.warn('[好友拜訪] 處理 visitSession 失敗：', err);
            } finally {
                setTimeout(() => {
                    if (window.__processingFriendVisitSessionKeys) delete window.__processingFriendVisitSessionKeys[sessionKey];
                }, 1000);
            }
        });
    });
};

window.sendFriendVisitRequest = async function(targetUid) {
    if (!targetUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;
    if (targetUid === myUid) return;

    const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[targetUid]) || {};

    try {
        if (window.refreshMyOnlinePresenceNow) await window.refreshMyOnlinePresenceNow({ force: true });

        const onlineInfo = window.fetchFriendOnlineInfoNow
            ? await window.fetchFriendOnlineInfoNow(targetUid)
            : (window.getFriendOnlineInfo ? window.getFriendOnlineInfo(targetUid, null, { mode: 'visit' }) : { online: false });
        const targetName = onlineInfo.name || meta.name || '對方';

        if (!onlineInfo.online) {
            window.showFriendSystemNotice('對方不在家……');
            return;
        }

        const friendSnap = await get(ref(window.GameLogic.db, `users/${myUid}/friends/${targetUid}`));
        if (!friendSnap.exists()) {
            window.showFriendSystemNotice('要先成為好蔥友才能拜訪喔');
            return;
        }

        const now = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();
        const requestData = {
            fromUid: myUid,
            fromName: window.GameLogic.myProfile.name || '匿名',
            fromColor: window.GameLogic.myProfile.color || '#fff',
            hostUid: targetUid,
            createdAt: now,
            updatedAt: now,
            status: 'pending',
            requestId: `${myUid}_${now}`,
            roomId: window.getCurrentServerRoomId ? window.getCurrentServerRoomId() : (window.GameLogic.currentServerRoom || '')
        };

        await set(ref(window.GameLogic.db, `users/${targetUid}/friendVisitRequests/${myUid}`), requestData);
        window.showFriendSystemNotice(`已送出去 ${targetName} 家的拜訪邀請`);
    } catch (err) {
        console.warn('[好友拜訪] 送出拜訪邀請失敗：', err);
        window.showFriendSystemNotice('拜訪邀請送出失敗，請稍後再試');
    }
};

window.openFriendVisitEntry = async function(uid) {
    if (!uid) return;
    await window.sendFriendVisitRequest(uid);
};

window.acceptCurrentFriendVisitRequest = function() {
    if (!window.__activeFriendVisitRequestUid) return;
    window.acceptFriendVisitRequest(window.__activeFriendVisitRequestUid);
};

window.rejectCurrentFriendVisitRequest = function() {
    if (!window.__activeFriendVisitRequestUid) return;
    window.rejectFriendVisitRequest(window.__activeFriendVisitRequestUid);
};

window.acceptFriendVisitRequest = async function(fromUid) {
    if (!fromUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;
    const myName = window.GameLogic.myProfile.name || '匿名';

    try {
        const now = window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now();
        const sessionId = `${myUid}_${fromUid}_${now}`;
        const updates = {};
        updates[`users/${myUid}/friendVisitRequests/${fromUid}`] = null;
        updates[`users/${fromUid}/friendVisitReplies/${myUid}`] = {
            status: 'accepted',
            command: 'enterDoghouse',
            needAck: true,
            hostUid: myUid,
            hostName: myName,
            guestUid: fromUid,
            createdAt: now,
            updatedAt: now,
            replyId: sessionId,
            sessionId: sessionId,
            ackPath: `users/${myUid}/doghousePlayers/${fromUid}`
        };
        updates[`users/${fromUid}/friendVisitSessions/${myUid}`] = {
            sessionId: sessionId,
            status: 'go',
            hostUid: myUid,
            hostName: myName,
            guestUid: fromUid,
            createdAt: now,
            updatedAt: now,
            retryCount: 0,
            needAck: true,
            ackPath: `users/${myUid}/doghousePlayers/${fromUid}`,
            source: 'visitAccepted'
        };

        await update(ref(window.GameLogic.db), updates);

        if (window.GameLogic.friendVisitRequests) delete window.GameLogic.friendVisitRequests[fromUid];
        window.closeFriendVisitRequestModal();
        window.showFriendSystemNotice('已答應拜訪邀請，準備回到你的狗窩。');

        if (window.enterFriendDoghouse) {
            const enterOk = await window.enterFriendDoghouse(myUid, myName, { source: 'visitHostAccepted', guestUid: fromUid });
            if (!enterOk) console.warn('[好友拜訪] host 回自己狗窩切換未完成，仍保留線上狀態刷新。');
        }
    } catch (err) {
        console.warn('[好友拜訪] 接受拜訪邀請失敗：', err);
        window.showFriendSystemNotice('接受拜訪邀請失敗，請稍後再試');
    }
};

window.rejectFriendVisitRequest = async function(fromUid) {
    if (!fromUid || !window.GameLogic || !window.GameLogic.currentUser || !window.GameLogic.db) return;

    const myUid = window.GameLogic.currentUser.uid;
    const myName = window.GameLogic.myProfile.name || '匿名';

    try {
        const updates = {};
        updates[`users/${myUid}/friendVisitRequests/${fromUid}`] = null;
        updates[`users/${fromUid}/friendVisitReplies/${myUid}`] = {
            status: 'rejected',
            hostUid: myUid,
            hostName: myName,
            createdAt: window.getFirebaseServerNow ? window.getFirebaseServerNow() : Date.now()
        };

        await update(ref(window.GameLogic.db), updates);

        if (window.GameLogic.friendVisitRequests) delete window.GameLogic.friendVisitRequests[fromUid];
        window.closeFriendVisitRequestModal();
        window.showFriendSystemNotice('已回覆：下次再來');
    } catch (err) {
        console.warn('[好友拜訪] 拒絕拜訪邀請失敗：', err);
        window.showFriendSystemNotice('拒絕拜訪邀請失敗，請稍後再試');
    }
};
// ====== 好蔥友基礎系統結束 ======
// ====== 洋蔥手機：目前在線＋最近私訊（房間隔離版） ======
window.getPMChatId = function(uidA, uidB) {
    return [uidA, uidB].sort().join('_');
};

window.phoneEscapeHtml = function(val) {
    return String(val ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
};

window.isMobileTouchViewport = function() {
    try {
        return window.matchMedia('(max-width: 768px), (orientation: portrait), (pointer: coarse)').matches;
    } catch (_) {
        return window.innerWidth <= 768;
    }
};

window.clearUiBlockersAfterModal = function(options = {}) {
    try {
        if (typeof window.closeQuickMenu === 'function') {
            window.closeQuickMenu();
        } else {
            ['magic-menu-blocker', 'quick-select-menu'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.style.display = 'none';
            });
        }

        ['prince-cat-menu', 'action-menu'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });

        if (options.blur !== false) {
            const active = document.activeElement;
            if (active && ['INPUT', 'TEXTAREA', 'SELECT'].includes(active.tagName)) {
                active.blur();
            }
        }

        if (window.scheduleMobileViewportRefresh) {
            window.scheduleMobileViewportRefresh();
            setTimeout(() => window.scheduleMobileViewportRefresh(), 260);
        }
    } catch (err) {
        console.warn('[手機版 UI] 清理殘留攔截層失敗，已略過：', err);
    }
};

window.isValidPMContactRecord = function(contact) {
    if (!contact || typeof contact !== 'object') return false;

    const lastMessage = String(contact.lastMessage || '').trim();
    const lastTime = Number(contact.lastTime || 0);

    return lastMessage.length > 0 && lastTime > 0;
};

window.applyValidUnreadPMs = function(rawUnread = {}, recentContacts = null) {
    rawUnread = (rawUnread && typeof rawUnread === 'object') ? rawUnread : {};

    const contacts = (recentContacts && typeof recentContacts === 'object')
        ? recentContacts
        : (window.GameLogic.pmContacts || {});

    const myUid = window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : null;
    const currentRoomId = window.getCurrentServerRoomId ? window.getCurrentServerRoomId() : (window.GameLogic.currentServerRoom || '');
    const validUnread = {};
    const cleanupUpdates = {};

    Object.keys(rawUnread).forEach(uid => {
        if (!uid || uid === myUid) return;

        const unreadVal = rawUnread[uid];
        const unreadRoomId = (unreadVal && typeof unreadVal === 'object') ? unreadVal.roomId : null;

        if (unreadRoomId && unreadRoomId !== currentRoomId) {
            return;
        }

        const contact = contacts[uid] || {};
        if (window.isValidPMContactRecord(contact)) {
            validUnread[uid] = unreadVal || true;
            return;
        }

        // 只有新格式且明確屬於目前房間的髒資料才安全清掉；舊格式 true 只忽略，不冒險刪除。
        if (myUid && unreadRoomId === currentRoomId) {
            cleanupUpdates[`users/${myUid}/unreadPMs/${uid}`] = null;
        }
    });

    window.GameLogic.unreadPMs = rawUnread;
    window.GameLogic.validUnreadPMs = validUnread;

    if (Object.keys(cleanupUpdates).length > 0 && window.GameLogic.db) {
        update(ref(window.GameLogic.db), cleanupUpdates)
            .catch(err => console.warn('[私訊紅點] 清理目前房間髒未讀資料失敗，已改用忽略處理：', err));
    }

    window.updateUnreadGlow();

    const inventoryModal = document.getElementById('inventory-modal');
    if (inventoryModal && inventoryModal.style.display === 'block') {
        window.openInventoryModal();
    }

    return validUnread;
};

window.normalizeUnreadPMs = async function(rawUnread = {}) {
    const myUid = window.GameLogic.currentUser ? window.GameLogic.currentUser.uid : null;
    if (!myUid) {
        window.GameLogic.unreadPMs = {};
        window.GameLogic.validUnreadPMs = {};
        window.updateUnreadGlow();
        return {};
    }

    const seq = (window.__unreadNormalizeSeq || 0) + 1;
    window.__unreadNormalizeSeq = seq;

    try {
        const recentSnap = await get(ref(window.GameLogic.db, window.getServerRoomPath(`pmContacts/${myUid}`)));
        if (seq !== window.__unreadNormalizeSeq) return window.GameLogic.validUnreadPMs || {};

        const recentContacts = recentSnap.val() || {};
        window.GameLogic.pmContacts = recentContacts;

        return window.applyValidUnreadPMs(rawUnread, recentContacts);
    } catch (err) {
        console.warn('[私訊紅點] 驗證未讀資料失敗，暫時不亮紅點避免誤判：', err);
        window.GameLogic.unreadPMs = rawUnread || {};
        window.GameLogic.validUnreadPMs = {};
        window.updateUnreadGlow();
        return {};
    }
};

window.hasValidUnreadPM = function(uid) {
    return !!(window.GameLogic.validUnreadPMs && window.GameLogic.validUnreadPMs[uid]);
};

window.closePhoneModal = function() {
    const phoneModal = document.getElementById('phone-modal');
    if (window.closeInventoryChildModal) {
        window.closeInventoryChildModal(phoneModal);
    } else {
        if (phoneModal) phoneModal.style.display = 'none';
        window.clearUiBlockersAfterModal();
    }
};

window.safePhoneColor = function(val) {
    const color = String(val || '#fff').trim();
    return /^#[0-9a-fA-F]{3,8}$/.test(color) ? color : '#fff';
};

window.isFreshPhoneOnlinePlayer = function(player) {
    if (window.isFreshOnlinePlayer) return window.isFreshOnlinePlayer(player, { mode: 'visit' });
    if (!player || typeof player !== 'object') return false;

    const lastActive = Number(player.lastActive || 0);
    if (!lastActive) return false;

    return Date.now() - lastActive <= 5 * 60 * 1000;
};

window.formatPMContactTime = function(ts) {
    const time = Number(ts || 0);
    if (!time) return '';

    const d = new Date(time);
    if (Number.isNaN(d.getTime())) return '';

    return d.toLocaleString('zh-TW', {
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
    });
};

window.makePhoneContactCard = function(uid, data, options = {}) {
    const name = data.name || '匿名';
    const color = window.safePhoneColor(data.color || '#fff');
    const isRecent = !!options.isRecent;
    const levelText = (!isRecent && data.level !== undefined && data.level !== null)
        ? `Lv.${window.phoneEscapeHtml(data.level)}`
        : (!isRecent ? 'Lv.?' : '');

    const unreadDot = window.hasValidUnreadPM(uid)
        ? '<span style="color:red; font-size:10px; margin-left:4px;">🔴</span>'
        : '';

    let subText = '';
    if (isRecent) {
        const lastMsg = data.lastMessage ? window.phoneEscapeHtml(String(data.lastMessage).slice(0, 60)) : '尚無訊息摘要';
        const timeText = window.formatPMContactTime(data.lastTime);
        subText = `<div class="phone-contact-sub">${lastMsg}${timeText ? `｜${timeText}` : ''}</div>`;
    } else {
        subText = `<div class="phone-contact-sub">目前在線${levelText ? `｜${levelText}` : ''}</div>`;
    }

    return `<div class="catalog-item phone-contact" data-contact-uid="${window.phoneEscapeHtml(uid)}">
        <div class="phone-contact-main">
            <div class="phone-contact-title" style="color:${color};">${window.phoneEscapeHtml(name)}${unreadDot}</div>
            ${subText}
        </div>
        <div class="phone-contact-actions">
            <button class="btn-secondary" style="color:#333;" data-phone-action="profile" data-uid="${window.phoneEscapeHtml(uid)}">查看</button>
            <button class="btn-primary" data-phone-action="pm" data-uid="${window.phoneEscapeHtml(uid)}">私訊</button>
        </div>
    </div>`;
};

window.bindPhoneContactButtons = function(contactsEl) {
    if (!contactsEl) return;

    contactsEl.querySelectorAll('[data-phone-action="profile"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.viewOtherProfile(btn.dataset.uid);
        });
    });

    contactsEl.querySelectorAll('[data-phone-action="pm"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();

            const uid = btn.dataset.uid;
            const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[uid]) || {};
            const name = meta.name || '匿名';
            const color = meta.color || '#fff';

            window.openPM(uid, name, color);
        });
    });

    contactsEl.querySelectorAll('[data-phone-action="accept-friend"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.acceptFriendRequest(btn.dataset.uid);
        });
    });

    contactsEl.querySelectorAll('[data-phone-action="reject-friend"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.rejectFriendRequest(btn.dataset.uid);
        });
    });

    contactsEl.querySelectorAll('[data-phone-action="love-entry"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.openFriendLoveEntry(btn.dataset.uid);
        });
    });

    contactsEl.querySelectorAll('[data-phone-action="visit-entry"]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            window.openFriendVisitEntry(btn.dataset.uid);
        });
    });
};

window.openPhoneModal = async function() {
    if (window.__phoneRendering) return;
    window.__phoneRendering = true;

    const inventoryModal = document.getElementById('inventory-modal');
    const phoneModal = document.getElementById('phone-modal');
    const contactsEl = document.getElementById('phone-contacts');

    try {
        window.clearUiBlockersAfterModal({ blur: false });

        if (inventoryModal) inventoryModal.style.display = 'none';
        if (phoneModal) phoneModal.style.display = 'block';
        if (!contactsEl) return;

        contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">讀取洋蔥手機中...</div>';

        if (!window.GameLogic.currentUser) {
            contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">請先登入後再使用洋蔥手機</div>';
            return;
        }

        const myUid = window.GameLogic.currentUser.uid;
        const roomName = window.getCurrentServerRoomName();
        const phoneContactMeta = {};
        const subtitleEl = document.getElementById('phone-subtitle');
        const friendsBtn = document.getElementById('phone-friends-btn');
        if (subtitleEl) subtitleEl.innerText = '點擊聯絡人發送私訊';
        if (friendsBtn) {
            friendsBtn.innerText = '我的好友';
            friendsBtn.onclick = (e) => {
                if (window.popPhoneHeaderParticles) window.popPhoneHeaderParticles(e);
                if (window.openMyFriendsPhonePanel) window.openMyFriendsPhonePanel();
            };
        }

        const [onlineSnap, recentSnap, friendRequestsSnap] = await Promise.all([
            get(ref(window.GameLogic.db, window.getServerRoomPath('onlinePlayers'))),
            get(ref(window.GameLogic.db, window.getServerRoomPath(`pmContacts/${myUid}`))),
            get(ref(window.GameLogic.db, `users/${myUid}/friendRequests`))
        ]);

        const onlinePlayers = Object.assign(
            {},
            window.GameLogic.onlinePlayers || {},
            onlineSnap.val() || {}
        );

        window.GameLogic.onlinePlayers = onlinePlayers;

        const recentContacts = recentSnap.val() || {};
        const friendRequests = window.normalizeFriendRequests ? window.normalizeFriendRequests(friendRequestsSnap.val() || {}) : {};
        window.GameLogic.pmContacts = recentContacts;
        window.GameLogic.friendRequests = friendRequests;
        window.applyValidUnreadPMs(window.GameLogic.unreadPMs || {}, recentContacts);

        const onlineUids = Object.keys(onlinePlayers)
            .filter(uid => uid !== myUid && window.isFreshPhoneOnlinePlayer(onlinePlayers[uid]))
            .sort((a, b) => {
                const nameA = (onlinePlayers[a] && onlinePlayers[a].name) || '匿名';
                const nameB = (onlinePlayers[b] && onlinePlayers[b].name) || '匿名';
                return nameA.localeCompare(nameB, 'zh-Hant');
            })
            .slice(0, 80);

        const onlineUidSet = {};
        onlineUids.forEach(uid => { onlineUidSet[uid] = true; });

        let html = `
            <div style="font-size:11px; color:#fff; text-shadow:1px 1px 2px #000; margin-bottom:8px;">
                目前房間：${window.phoneEscapeHtml(roomName)}
            </div>
            <div style="color:#ffcc00; font-weight:bold; text-align:left; margin:6px 0 4px 0; border-bottom:1px solid rgba(255,255,255,0.25); padding-bottom:3px;">
                🟢 目前在線
            </div>
        `;

        const friendRequestUids = Object.keys(friendRequests)
            .sort((a, b) => Number(friendRequests[b].createdAt || 0) - Number(friendRequests[a].createdAt || 0));

        if (friendRequestUids.length > 0) {
            html += `
                <div style="color:#ffcc00; font-weight:bold; text-align:left; margin:6px 0 4px 0; border-bottom:1px solid rgba(255,255,255,0.25); padding-bottom:3px;">
                    🌱 好蔥友邀請
                </div>
            `;
            friendRequestUids.forEach(fromUid => {
                html += window.makePhoneFriendRequestCard(fromUid, friendRequests[fromUid]);
            });
        }

        if (onlineUids.length === 0) {
            html += '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000; font-size:13px; margin-bottom:8px;">目前房間沒有其他在線玩家</div>';
        } else {
            onlineUids.forEach(uid => {
                const p = onlinePlayers[uid] || {};
                const data = {
                    uid: uid,
                    name: p.name || '匿名',
                    color: p.color || '#fff',
                    level: p.level
                };

                phoneContactMeta[uid] = data;
                html += window.makePhoneContactCard(uid, data, { isRecent: false });
            });
        }

        const recentList = Object.keys(recentContacts)
            .filter(uid => uid !== myUid && !onlineUidSet[uid])
            .map(uid => {
                const c = recentContacts[uid] || {};
                return {
                    uid: uid,
                    name: c.name || '匿名',
                    color: c.color || '#fff',
                    lastMessage: c.lastMessage || '',
                    lastTime: Number(c.lastTime || 0)
                };
            })
            .filter(c => window.isValidPMContactRecord(c))
            .sort((a, b) => Number(b.lastTime || 0) - Number(a.lastTime || 0))
            .slice(0, 50);

        html += `
            <div style="color:#ffcc00; font-weight:bold; text-align:left; margin:10px 0 4px 0; border-bottom:1px solid rgba(255,255,255,0.25); padding-bottom:3px;">
                💬 最近私訊
            </div>
        `;

        if (recentList.length === 0) {
            html += '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000; font-size:13px;">目前沒有離線的最近私訊</div>';
        } else {
            recentList.forEach(c => {
                phoneContactMeta[c.uid] = c;
                html += window.makePhoneContactCard(c.uid, c, { isRecent: true });
            });
        }

        contactsEl.innerHTML = html;
        window.GameLogic.phoneContactMeta = phoneContactMeta;

        window.bindPhoneContactButtons(contactsEl);
    } catch (err) {
        console.warn('[洋蔥手機] 讀取目前在線與最近私訊失敗：', err);
        if (contactsEl) {
            contactsEl.innerHTML = '<div style="text-align:center; color:#fff; text-shadow: 1px 1px 2px #000;">洋蔥手機讀取失敗，請稍後再試</div>';
        }
    } finally {
        window.__phoneRendering = false;
        if (window.scheduleMobileViewportRefresh) window.scheduleMobileViewportRefresh();
    }
};

window.openPM = async function(targetUid, targetName, targetColor = '#fff') {
    if (!targetUid || !window.GameLogic.currentUser) return;

    const meta = (window.GameLogic.phoneContactMeta && window.GameLogic.phoneContactMeta[targetUid]) || {};
    const safeTargetName = targetName || meta.name || '匿名';
    const safeTargetColor = window.safePhoneColor(targetColor || meta.color || '#fff');

    window.clearUiBlockersAfterModal({ blur: false });

    document.getElementById('phone-modal').style.display = 'none';
    document.getElementById('pm-modal').style.display = 'block';
    document.getElementById('pm-title').innerText = `💬 與 ${safeTargetName} 密語`;

    window.currentPMUid = targetUid;
    window.currentPMTargetName = safeTargetName;
    window.currentPMTargetColor = safeTargetColor;

    let myUid = window.GameLogic.currentUser.uid;
    let chatId = window.getPMChatId(myUid, targetUid);
    let pmPath = window.getServerRoomPath(`privateChats/${chatId}`);

    // 開啟該對象私訊時，立即清掉本地與 Firebase 未讀，紅點不要等下一次監聽才消失。
    if (window.GameLogic.unreadPMs) delete window.GameLogic.unreadPMs[targetUid];
    if (window.GameLogic.validUnreadPMs) delete window.GameLogic.validUnreadPMs[targetUid];
    window.updateUnreadGlow();

    remove(ref(window.GameLogic.db, `users/${myUid}/unreadPMs/${targetUid}`))
        .catch(err => console.warn('[私訊] 清除未讀狀態失敗，已先更新本地紅點：', err));

    if (window.pmUnsubscribe) window.pmUnsubscribe();

    window.pmUnsubscribe = onValue(ref(window.GameLogic.db, pmPath), snap => {
        const msgs = snap.val() || {};
        const box = document.getElementById('pm-chat-box');
        if (!box) return;

        const msgList = Object.values(msgs)
            .sort((a, b) => Number(a.time || 0) - Number(b.time || 0))
            .slice(-80);

        box.innerHTML = msgList.map(m => {
            const msgText = window.phoneEscapeHtml(m.msg || '');
            const nameText = window.phoneEscapeHtml(m.name || '匿名');

            if (m.uid === myUid) {
                return `<div style="text-align:right; margin-bottom: 8px;"><div class="pm-bubble-me">${msgText}</div></div>`;
            }

            return `<div style="text-align:left; margin-bottom: 8px;"><div class="pm-bubble-other"><div style="font-size:11px; color:#558b2f; font-weight:bold; margin-bottom:2px;">${nameText}</div>${msgText}</div></div>`;
        }).join('');

        box.scrollTop = box.scrollHeight;
    });

    if (window.scheduleMobileViewportRefresh) window.scheduleMobileViewportRefresh();
};

window.closePM = function() {
    if (window.pmUnsubscribe) {
        window.pmUnsubscribe();
        window.pmUnsubscribe = null;
    }

    const input = document.getElementById('pm-input');
    if (input) input.blur();

    document.getElementById('pm-modal').style.display = 'none';

    window.clearUiBlockersAfterModal();

    // 返回聯絡人時順手重新整理，讓最近私訊區即時更新。
    window.openPhoneModal();
};

window.sendPM = async function() {
    let input = document.getElementById('pm-input');
    let msg = input ? input.value.trim() : '';
    if (!msg || !window.currentPMUid || !window.GameLogic.currentUser) return;

    let myUid = window.GameLogic.currentUser.uid;
    let targetUid = window.currentPMUid;
    let chatId = window.getPMChatId(myUid, targetUid);
    let pmPath = window.getServerRoomPath(`privateChats/${chatId}`);

    const sendTime = Date.now();
    const roomId = window.getCurrentServerRoomId ? window.getCurrentServerRoomId() : (window.GameLogic.currentServerRoom || '');
    const myName = (window.GameLogic.myProfile && window.GameLogic.myProfile.name) || '匿名';
    const myColor = window.safePhoneColor((window.GameLogic.myProfile && window.GameLogic.myProfile.color) || '#fff');

    const targetName = window.currentPMTargetName || '匿名';
    const targetColor = window.safePhoneColor(window.currentPMTargetColor || '#fff');

    try {
        await push(ref(db, pmPath), {
            uid: myUid,
            name: myName,
            msg: msg,
            time: sendTime
        });

        const updates = {};

        // 新格式：保留原本 users/{uid}/unreadPMs/{fromUid} 位置，但加入房間與訊息資訊供紅點驗證。
        updates[`users/${targetUid}/unreadPMs/${myUid}`] = {
            roomId: roomId,
            chatId: chatId,
            fromUid: myUid,
            time: sendTime,
            lastMessage: msg
        };

        // 目前入口房間內的最近私訊清單。
        updates[window.getServerRoomPath(`pmContacts/${myUid}/${targetUid}`)] = {
            uid: targetUid,
            name: targetName,
            color: targetColor,
            lastMessage: msg,
            lastTime: sendTime
        };

        updates[window.getServerRoomPath(`pmContacts/${targetUid}/${myUid}`)] = {
            uid: myUid,
            name: myName,
            color: myColor,
            lastMessage: msg,
            lastTime: sendTime
        };

        await update(ref(db), updates);

        input.value = '';

        if (window.isMobileTouchViewport()) input.blur();
        window.clearUiBlockersAfterModal({ blur: false });
    } catch (err) {
        console.warn('[私訊] 發送或更新最近私訊失敗：', err);
        alert('私訊發送失敗，請打開 F12 Console 查看錯誤。');
    }
};
